NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'I Chronicles'

CHAPTERS = {
    1: {
        1: 'Adam, Set, Enos.',
        2: 'Kenan, Mahalalel, Jered.',
        3: 'Chanok, Metuselach, Lemek.',
        4: 'Noë, Sem, Cham, Japhet.',
        5: 'Japhets Söhne sind Gomer, Magog, Madai, Javan, Tubal, Mosek und Tiras.',
        6: 'Gomers Söhne sind Askenaz, Riphat und Togarma.',
        7: 'Javans Söhne sind Elisa, Tarsis, Kittim und Rodanim.',
        8: 'Chams Söhne sind Kusch und Misraim, Put und Kanaan.',
        9: 'Des Kusch Söhne sind Seba, Chavila, Sabta, Regma und Sabteka, Regmas Söhne sind Seba und Dedan.',
        10: 'Und Kusch zeugte Nimrod. Dieser fing an, auf Erden ein Held zu werden.',
        11: 'Und Misraim zeugte die Luditer, die Anamiter, die Lehabiter, die Naphtuchiter,',
        12: 'die Patrusiter und die Kasluchiter sowie die Kaphtoriter, von denen die Philister auszogen.',
        13: 'Und Kanaan zeugte Sidon als seinen Erstgeborenen und Chet,',
        14: 'sodann die Jebusiter, Amoriter, Girgasiter,',
        15: 'Chiviter, Arkiter, Siniter,',
        16: 'Arvaditer, Semariter und Chamatiter',
        17: 'Sems Söhne sind Elam, Assur, Arphaksad, Lud, Aram, Us, Chul, Geter und Mesek.',
        18: 'Und Arphaksad zeugte den Selach und Selach den Eber.',
        19: 'Zwei Söhne wurden Eber geboren. Des einen Name war Peleg. Denn in seinen Tagen ward die Erde zerteilt. Sein Bruder hieß Joktan.',
        20: 'Und Joktan zeugte Almodad, Seleph, Chazarmavet, Jerach,',
        21: 'Hadoram, Uzal, Dikla,',
        22: 'Ebal, Abimael, Seba,',
        23: 'Ophir, Chavila und Jobab. All diese sind Joktans Söhne.',
        24: 'Sem, Arphaksad, Selach,',
        25: 'Eber, Peleg, Rëu,',
        26: 'Serug, Nachor, Terach,',
        27: 'Abram, das ist Abraham.',
        28: 'Abrahams Söhne waren Isaak und Ismael.',
        29: 'Dies sind ihre Geschlechtsfolgen: Ismaëls Erstgeborener ist Nebajot. Dann folgen Kedar, Adbeel, Mibsam,',
        30: 'Misma, Duma, Massa, Chadad, Tema,',
        31: 'Jetur, Naphis und Kedma. Dies sind die Söhne Ismaëls.',
        32: 'Keturas, des Nebenweibes Abrahams, Söhne sind Zimran, Joksan, Medan, Midian, Isbak und Suach; diese hat sie geboren. Joksans Söhne sind Seba und Dedan.',
        33: 'Midians Söhne sind Epha, Epher und Chanok, Abida und Eldaa. Alle diese sind Söhne der Ketura.',
        34: 'Und Abraham zeugte den Isaak. Isaaks Söhne sind Esau und Israel.',
        35: 'Esaus Söhne sind Eliphaz, Rëuel, Jeus, Jalam und Korach.',
        36: 'Des Eliphaz Söhne sind Teman, Omar, Sephi, Gatam, Kenaz, Timna und Amalek.',
        37: 'Rëuels Söhne sind Nachat, Zerach, Samma und Mizza.',
        38: 'Und Seïrs Söhne sind Lotan, Sobal, Sibon, Ana, Dison, Eser und Disan.',
        39: 'Lotans Söhne sind Chori und Homam. Timna ist Lotans Schwester.',
        40: 'Sobals Söhne sind Aljan, Manachat, Ebal, Sephi und Onam. Sibons Söhne sind Ajja und Ana.',
        41: 'Anas Söhne sind: Dison. Und Disons Söhne sind Chamram, Esban, Itran und Keran.',
        42: 'Esers Söhne sind Bilhan, Zaavan und Jakan. Disans Söhne sind Us und Aran.',
        43: 'Dies sind die Könige, die im Lande Edom herrschten, bevor ein König der Israeliten war:',
        44: 'Bela, Beors Sohn, und seine Stadt hieß Dinhaba. Als Bela starb, ward des Serach Sohn, Jobab, aus Bosra an seiner Statt König.',
        45: 'Als Jobab starb, ward Chusam aus dem Lande der Temaniter an seiner Statt König.',
        46: 'Als Chusam starb, ward an seiner Statt König Bedads Sohn, Hadad, der Midian auf Moabs Gefilde schlug. Seine Stadt hieß Avit.',
        47: 'Als Hadad starb, ward Samla aus Masreha an seiner Statt König.',
        48: 'Als Samla starb, ward Saul aus Rechobot am Strom an seiner Statt König.',
        49: 'Als Saul starb, ward Akbors Sohn, Baalchanan, an seiner Statt König.',
        50: 'Als Baalchanan starb, ward Hadad an seiner Statt König. Seine Stadt hieß Pai, und sein Weib, Matreds Tochter und Mezahabs Enkelin, hieß Mehetabel.',
        51: 'Als Hadad starb, gab es nur noch Häuptlinge in Edom: die Häuptlinge Timna, Alja, Jetet,',
        52: 'Oholibama, Ela, Pinon,',
        53: 'Kenaz, Teman, Mibsar,',
        54: 'Magdiel und Iram. Dies sind Edoms Häuptlinge.',
    },
    2: {
        1: 'Dies sind Israels Söhne: Ruben, Simeon, Levi und Juda, Issakar und Zabulon,',
        2: 'Dan, Joseph und Benjamin, Naphtali, Gad und Asser.',
        3: 'Judas Söhne sind: Er, Onan und Sela, drei, die ihm von Suas Tochter, der Kanaaniterin, geboren sind. Judas Erstgeborener machte sich dem Herrn mißfällig, und dieser ließ ihn sterben.',
        4: 'Seine Schwiegertochter Tamar aber gebar ihm Peres und Zerach. Aller Söhne Judas sind es fünf.',
        5: 'Des Peres Söhne sind Chesron und Chamul.',
        6: 'Des Zerach Söhne sind Zimri, Etan, Heman, Kalkol und Dara, zusammen fünf.',
        7: 'Des Karmi Söhne sind: Akar, der Israel ins Unglück stürzte, da er sich am Geweihten pflichtvergessen vergriff.',
        8: 'Etans Söhne sind: Azarja.',
        9: 'Chesrons Söhne, die ihm geboren worden, sind Jerachmeel, Ram und Kelubai.',
        10: 'Ram zeugte Aminadab und Aminadab den Nachson, den Judäerfürsten.',
        11: 'Nachson zeugte Salma und Salma den Boaz.',
        12: 'Boaz zeugte Obed und Obed den Isai.',
        13: 'Und Isai zeugte als seinen Erstgeborenen Eliab, als zweiten Abinadab, als dritten Sima,',
        14: 'als vierten Natanael, als fünften Raddai,',
        15: 'als sechsten Osem und als siebten David.',
        16: 'Ihre Schwestern sind Seruja und Abigail. Der Seruja Söhne sind Absai, Joab und Asael, drei.',
        17: 'Abigail gebar Amasa. Des Amasa Vater ist der Ismaeliter Jeter.',
        18: 'Chesrons Sohn Kaleb hat Azuba geheiratet. Dies sind ihre Söhne: Jeser, Sobab und Ardon.',
        19: 'Als Azuba starb, nahm sich Kaleb die Ephrat. Sie gebar ihm den Chur.',
        20: 'Chur aber zeugte Uri und Uri den Besalel.',
        21: 'Hernach ist Chesron zur Tochter Makirs, des Vaters von Gilead, gegangen und hat sie geheiratet, als er sechzig Jahre alt war, und sie gebar ihm den Segub.',
        22: 'Segub aber zeugte Jair. Dieser besaß dreiundzwanzig Städte im Lande Gilead.',
        23: 'Aber die Gesuriter und die Aramäer nahmen ihnen Jairs Zeltdörfer weg, Kenat mit seinen Tochterstädten, sechzig Städte. Alle diese waren die Söhne des Gileadvaters Makir.',
        24: 'Nach Chesrons Tod ging Kaleb nach Ephrat. Chesrons Weib aber war Abia, und sie gebar ihm Aschur, Tekoas Vater.',
        25: 'Jerachmeels, des Erstgeborenen des Chesron, Söhne waren der Erstgeborene Ram, dann Buna, Oren, Osem und Achia.',
        26: 'Jerachmeel hatte noch ein anderes Weib mit Namen Atara. Sie war Onams Mutter.',
        27: 'Rams, des Erstgeborenen von Jerachmeel, Söhne sind Maan, Jamin und Eker.',
        28: 'Onams Söhne sind Sammai und Jada. Sammais Söhne sind Nadab und Abisur.',
        29: 'Abisurs Weib hieß Abichail. Sie gebar ihm Achban und Molid.',
        30: 'Nadabs Söhne sind Seled und Appaim. Seled starb kinderlos.',
        31: 'Appaims Söhne sind Isi, Isis Söhne sind: Sesan, Sesans Söhne sind Achlai.',
        32: 'Jadas, Sammais Bruders, Söhne sind Jeter und Jonatan. Jeter aber starb kinderlos.',
        33: 'Jonatans Söhne sind Pelet und Zaza. Dies sind Jerachmeels Söhne.',
        34: 'Sesan hatte keine Söhne gehabt, sondern nur Töchter. Dagegen besaß Sesan einen ägyptischen Sklaven namens Jarcha.',
        35: 'Seinem Sklaven Jarcha aber gab Sesan seine Tochter zum Weibe, und sie gebar ihm den Attai.',
        36: 'Attai zeugte Natan und Natan den Zabad.',
        37: 'Zabad zeugte Ephlal und Ephlal den Obed.',
        38: 'Obed zeugte Jehu und Jehu den Azarja.',
        39: 'Azarja hat Cheles gezeugt und Cheles den Elasa.',
        40: 'Elasa zeugte Sismai und Sismai den Sallum.',
        41: 'Sallum zeugte Jekamja und Jekamja den Elisama.',
        42: 'Kalebs, Jerachmeels Bruders, Söhne sind sein Erstgeborener Mesa, das ist Ziphs Vater, und die Söhne Maresas, des Vaters von Chebron.',
        43: 'Chebrons Söhne sind Korach, Tappuach, Rekem und Sema.',
        44: 'Sema zeugte Jorkams Vater Racham, und Rekem zeugte Sammai.',
        45: 'Sammais Sohn ist Maon, und Maon ist der Vater von Bet Sur.',
        46: 'Kalebs Nebenweib Epha gebar Charan, Mosa und Gazez. Charan zeugte Gazez.',
        47: 'Jahdais Söhne sind Regem, Jotam, Gesan, Pelet, Epha und Saaph.',
        48: 'Kalebs Nebenweib Maaka gebar Seber und Tirchana.',
        49: 'Sie gebar auch Saaph, den Vater von Madmanna, Seva, den Vater von Makbenna, und den Vater von Giba. Kalebs Tochter war Aksa.',
        50: 'Dies sind Kalebs Söhne: Churs, des Erstgeborenen des Ephrat, Söhne sind Sobal, der Vater von Kirjat Jearim,',
        51: 'Salma, der Vater von Bethlehem, und Chareph, der Vater von Bet Gader.',
        52: 'Sobal, Kirjat Jearims Vater, hatte zu Söhnen Haroeh, die Hälfte der Menuchot',
        53: 'und die Sippen Kirjat Jearims, die Itriter, Putiter, Sumatiter und Misraiter. Von diesen stammen die Saratiter und die Estauliter.',
        54: 'Salmas Söhne sind Bethlehem und die Netophatiter, Aterot, Bet Joab und die Hälfte der Manachtiter und der Sariter',
        55: 'und die Sippen der Sopherim, die in Jabes wohnen, die Tiratiter, Simatiter und Sukatiter. Dies sind die Kiniter, die von Chamot, Bet Rekabs Vater, stammen.',
    },
    3: {
        1: 'Dies sind Davids Söhne, die ihm zu Hebron geboren sind: der Erstgeborene Amnon von der Achinoam aus Jezreel; ein zweiter Daniel, von der Abigail aus Karmel,',
        2: 'der dritte Absalom, von des Königs von Gesur, Talmai, Tochter Maaka, der vierte Adonia, Chaggits Sohn,',
        3: 'der fünfte Sephatja von der Abital, der sechste Itram von seinem Weib Egla.',
        4: 'Sechs sind ihm zu Hebron geboren. Er regierte hier sieben Jahre sechs Monate, und in Jerusalem regierte er dreiunddreißig Jahre.',
        5: 'Folgende sind ihm zu Jerusalem geboren: Sima, Sobab, Natan und Salomo, vier von Ammiels Tochter Batsua,',
        6: 'ferner Ibchar, Elisua, Eliphelet,',
        7: 'Nogach, Nepheg, Japhia,',
        8: 'Elisama, Eljada und Eliphelet, neun,',
        9: 'alle Davids Söhne außer den Söhnen seiner Nebenweiber. Ihre Schwester ist Tamar.',
        10: 'Salomos Sohn ist Rechabeam, dessen Sohn Abia, dessen Sohn Asa, dessen Sohn Josaphat,',
        11: 'dessen Sohn Joram, dessen Sohn Achazja, dessen Sohn Joas,',
        12: 'dessen Sohn Amasja, dessen Sohn Azarja, dessen Sohn Jotam,',
        13: 'dessen Sohn Achaz, dessen Sohn Ezechias, dessen Sohn Manasse,',
        14: 'dessen Sohn Amon, dessen Sohn Josias.',
        15: 'Des Josias Söhne sind der Erstgeborene Jochanan, der zweite Jojakim, der dritte Sedekia, der vierte Sallum.',
        16: 'Jojakims Söhne sind sein Sohn Jechonja und sein Sohn Sedekia.',
        17: 'Die Söhne Jechonjas, des Gefangenen, sind sein Sohn Sealtiel,',
        18: 'Malkiram, Pedaja, Senassar, Jekamja, Hosanna und Nedabja.',
        19: 'Pedajas Söhne sind Zerubbabel und Simei - Zerubbabels Sohn ist Mesullam - sowie Chananja. Ihre Schwester ist Selomit.',
        20: 'Ferner Chasubal, Ohel, Berekja, Chasadja, Jusab, Chesed, fünf.',
        21: 'Chananjas Söhne sind Pelatja und Jesaja und Rephaias, Arnons, Obadjas und Sekanjas Söhne.',
        22: 'Sekanjas Söhne sind: Semaja und Semajas Söhne sind Chattus, Igal, Bariach, Nearja und Saphat, sechs.',
        23: 'Nearjas Söhne sind Eljoënai, Chizkia und Azrikam, drei.',
        24: 'Eljoënais Söhne sind Hodaiva, Eljasib, Pelaja, Akkub, Jochanan, Dejala und Anani, sieben.',
    },
    4: {
        1: 'Judas Söhne sind Peres, Chesron, Karmi, Chur und Sobal.',
        2: 'Sobals Sohn Reaja zeugte Jachat und Jachat den Achumai und den Lahad. Dies sind die Geschlechter der Soratiter.',
        3: 'Diese haben Etam zum Vater: Jezreel, Sima und Idbas. Ihre Schwester heißt Haslelponi.',
        4: 'Ferner Penuel, Gedors Vater, und Husas Vater Ezer. Dies sind die Söhne Churs, des Erstgeborenen Ephrats, des Vaters von Bethlehem.',
        5: 'Tekoas Vater Aschur hatte zwei Weiber, Chela und Naara.',
        6: 'Naara gebar ihm Achuzam, Chepher, Temni und die Achastariter. Dies sind Naaras Söhne.',
        7: 'Der Chela Söhne sind Seret, Ischar und Etnan.',
        8: 'Kos zeugte Anub und Sobeba sowie die Sippen des Acharchel, des Harumsohnes.',
        9: 'Jabes aber war vornehmer als seine Brüder. Seine Mutter hatte ihn Jabes genannt; sie sprach: "Ich habe ihn ja mit Schmerzen geboren."',
        10: 'Und Jabes rief zu Israels Gott: "Daß Du mich segnest und mein Gebiet vergrößerst und daß Deine Hand mit mir sei und Du Unheil ablenkest, auf daß ich keinen Verdruß habe!" Und Gott erfüllte das, worum er bat.',
        11: 'Suchas Bruder Kelub zeugte Mechir. Das ist der Vater von Eston.',
        12: 'Eston zeugte Bet Rapha, Paseach und Techinna, den Vater der Stadt Nachas. Dies sind die Männer von Reka.',
        13: 'Des Kenat Söhne sind Otniel und Seraja. Otniels Söhne sind: Chatat.',
        14: 'Meonotai zeugte Ophra, und Seraja den Joabs den Vater des Tales der Zimmerer. Denn sie waren Zimmerleute.',
        15: 'Des Jephunnesohnes Kaleb Söhne sind Ir, Ela und Naam, und der Sohn des Ela ist Kenaz.',
        16: 'Des Jehallel Söhne sind Ziph, Zipha, Tirja und Asarel.',
        17: 'Ezras Sohn ist Jeter; Mered aber heiratete Jalon. Und sie gebar Mirjam, Sammai und Isbach, des Estemoa Vater.',
        18: 'Sein jüdisches Weib aber hat Jered, den Vater Gedors, geboren, ferner Cheber, Sokos Vater, und Jekutiel, den Vater von Zanoach. Dies sind die Söhne der wirklichen Pharaotochter, die Mered geheiratet hat.',
        19: 'Die Söhne der Schwester Rachams und der Frau des Hodia sind der Garmiter, Kegilas Vater, und der Maakatiter Estemoa.',
        20: 'Simons Söhne sind Ammon, Rinna, Ben Chanan und Tilon. Iseis Söhne sind: Zochet und des Zochet Sohn.',
        21: 'Des Judasohnes Sela Söhne sind Er, der Vater von Leka, und Lada, der Vater von Maresa, sowie die Sippen des Hauses der Baumwollarbeiter zu Bet Asbe,',
        22: 'ferner Jokim und die Männer von Kozeba, sowie Joas und Saraph, die Moab erobert haben, und Jasubi Lechem. Die Geschichten aber sind alt.',
        23: 'Dies sind die Töpfer und Bewohner von Netaim und Gedera. Sie haben dort beim König in seinem Dienste gewohnt.',
        24: 'Simeons Söhne sind Nemuel und Jamin, Jarib, Zerach und Saul,',
        25: 'dessen Sohn war Sallum, dessen Sohn Mibsam und dessen Sohn Misma.',
        26: 'Mismas Söhne sind: sein Sohn Chammuel, dessen Sohn Zakkur und dessen Sohn Simei.',
        27: 'Simei aber besaß sechzehn Söhne und sechs Töchter. Seine Brüder aber hatten nicht viele Söhne. Und ihre ganze Sippe mehrte sich nicht so, daß sie den Judäern gleichgekommen wäre.',
        28: 'Sie wohnten in Beerseba, Molada, Chasar Sual,',
        29: 'in Bilha, Esem, Tolad,',
        30: 'in Betuel, Chorma, Siklag,',
        31: 'in Bet Markabot, Chasar Susim, in Bet Biri und Saarim. Dies waren ihre Städte, bis David König ward.',
        32: 'Ihre Dörfer waren Etam, Ajin, Rimmon, Token und Asan, fünf Städte.',
        33: 'Dazu all ihre Dörfer rings um diese Städte bis nach Baal hin. Dies waren ihre Wohnsitze. Sie hatten auch ihre eigene Sippenliste.',
        34: 'Ferner: Mesobab, Jamlek und des Amasja Sohn Josab.',
        35: 'Joel, Jehu, des Josibja Sohn und Enkel des Asielsohnes Seraja,',
        36: 'und Eljoënai, Jaakoba, Jesochaja, Asaja, Adiel, Jesimiel, Benaja',
        37: 'und Ziza, Siphis Sohn, Allons Enkel und Urenkel des Jedaja, des Sohnes des Simri und Enkels des Semaja.',
        38: 'Diese mit Namen Aufgeführten sind in ihren Sippen Fürsten, und das Haus ihrer Väter ist weit verbreitet.',
        39: 'Sie zogen vom Zugange nach Gedor, bis östlich vom Tal, um für ihre Herden Weiden zu suchen.',
        40: 'Sie fanden auch eine fette und gute Weide. Das Land war geräumig, ruhig und friedlich; denn die früheren Bewohner gehörten zu Cham.',
        41: 'Diese namentlich Aufgeführten kamen in den Tagen des Judakönigs Ezechias und schlugen Chams Gezelte und die der Mëuniter, die dort waren, und rotteten sie aus bis auf den heutigen Tag. Dann wohnten sie dort an ihrer Stelle. Denn dort war für ihre Herden Weide.',
        42: 'Ein Teil davon aber, von Simeons Söhnen, zog auf das Gebirge Sëir, fünfhundert Mann. An ihrer Spitze Pelatja, Nearja, Rephaja und Uziel, Iseis Söhne.',
        43: 'Sie schlugen Amaleks letzten Rest und wohnten dort bis auf diesen Tag.',
    },
    5: {
        1: 'Die Söhne Rubens, des Erstgeborenen Israels: - er war ja der Erstgeborene. Als er aber seines Vaters Lager entweihte, ist sein Erstgeburtsrecht den Söhnen des Israelsohnes Joseph verliehen worden. Aber die Erstgeburt ist nicht in die Sippenliste eingetragen worden.',
        2: 'Denn Juda ist unter seinen Brüdern mächtig geworden und ein Fürst, größer als jener. Das Erstgeburtsrecht gehört aber Joseph.',
        3: 'Rubens, des Erstgeborenen Israels, Söhne sind Chanok, Pallu, Chesron und Karmi.',
        4: 'Joels Söhne sind sein Sohn Semaja, dessen Sohn Gog, dessen Sohn Simei,',
        5: 'dessen Sohn Mika, dessen Sohn Reaja, dessen Sohn Baal,',
        6: 'dessen Sohn Beera, den Tilgat Pilneser, Assyriens König, in Gefangenschaft geführt hat. Er ist ein Fürst der Rubeniten.',
        7: 'Seine Brüder, nach seinen Sippen, nach der Abstammung verzeichnet, sind das Haupt Jeiel, ferner Zakarja',
        8: 'und Bela, des Azaz Sohn, Enkel des Sema und Urenkel Joels. Er wohnte zu Aroër und bis nach Nebo und Baal Meon.',
        9: 'Nach Osten hat er bis zum Rand der Wüste vom Euphratstrome an gewohnt. Denn ihre Herden im Lande Gilead sind zahlreich gewesen.',
        10: 'In Sauls Tagen stritten sie mit den Hagritern. Diese fielen in ihre Hand, und sie wohnten in deren Zelten auf Gileads ganzer Ostseite.',
        11: 'Gads Söhne haben im Lande Basan bis Saleka, ihnen gegenüber, gewohnt:',
        12: 'das Haupt Joel, Saphan, der zweite, und Janai und Saphat in Basan.',
        13: 'Ihre Brüder sind nach ihren Familien Mikael, Mesullam, Seba, Josai, Jakan, Zi und Eber, sieben.',
        14: 'Dies sind die Söhne Abichails, des Churisohns und Enkels des Jaroach, des Sohns Gileads und Enkels des Mikael, des Jesisaisohns und Enkels des Jachda, des Buzsohns.',
        15: 'Achi, Abdiels Sohn und Gunis Enkel, war ein Haupt ihrer Familien.',
        16: 'Sie wohnten in Gilead, Basan und dessen Tochterstädten, sowie auf allen Weidetriften Sarons bis an ihre Ausgänge.',
        17: 'Sie alle sind in des Judakönigs Jotam und des Israelskönigs Jeroboam Tagen aufgezeichnet worden.',
        18: 'Die Söhne Rubens und Gads sowie der Halbstamm Manasse, tapfere Männer, die Schild und Schwert trugen, den Bogen spannten und kampfgeübt waren, 440 und zwar leichtbewaffnete, kriegstüchtige Söldner,',
        19: 'führten mit den Hagritern Krieg, ebenso mit Jetur, Naphis und Nodab.',
        20: 'Ihnen ward gegen sie geholfen, und so wurden die Hagriter in ihre Hand gegeben, ebenso alle, die bei ihnen waren. Denn sie hatten im Kampfe zu Gott geschrieen, und er hatte sich von ihnen erbitten lassen, weil sie auf ihn vertraut hatten.',
        21: 'Sie führten deren Herden weg: 50.000 Kamele, 250.000 Schafe, 2.000 Esel und 100.000 Menschenseelen.',
        22: 'Denn viele waren durchbohrt gefallen, weil der Krieg von Gott kam. Dann wohnten sie an ihrer Stelle bis zu der Verbannung.',
        23: 'Auch die Söhne des Halbstammes Manasse haben im Lande Basan gewohnt bis Baal Hermon, Senir und bis zum Hermongebirge. Sie waren zahlreich.',
        24: 'Dies sind ihre Familienhäupter: Epher, Isei, Eliel, Azriel, Irmeja, Hodavja und Jachdiel, tapfere Krieger, berühmte Männer, Häupter in ihren Familien.',
        25: 'Sie waren aber gegen den Gott ihrer Väter treulos und buhlten mit den Göttern der Landesvölker, die Gott vor ihnen vertilgt hatte.',
        26: 'So reizte Israels Gott die Wut des Assyrerkönigs Pul, ebenso die Wut des Assyrerkönigs Tilgat Pilneser und ließ sie die Rubeniten, Gaditen und den Halbstamm Manasse wegführen und sie nach Chelach und zum Chabor bringen, nach Hara und zum Flusse Gozan bis auf diesen Tag. Levis Söhne sind Gersom, Kehat und Merari. Kehats Söhne sind Amram, Ischar, Chebron und Uzziel. Amrams Kinder sind Aaron, Moses und Mirjam. Aarons Söhne sind Nadab, Abihu, Eleazar und Itamar. Eleazar zeugte Pinechas und Pinechas den Abisu. Abisu zeugte Bukki und Bukki den Uzzi. Uzzi zeugte Zerachja und Zerachja den Merajot. Merajot zeugte Amarja und Amarja den Achitub. Achitub zeugte Sadok und Sadok den Achimaas. Achimaas zeugte Azarja und Azarja den Jochanan, Jochanan zeugte Azarja - das ist der, der im Hause, das Salomo in Jerusalem gebaut, Priesterdienste getan hat. Azarja aber zeugte Amarja und Amarja den Achitub. Achitub zeugte Sadok und Sadok den Sallum. Sallum zeugte Chilkia und Chilkia den Azarja. Azarja zeugte Seraja und Seraja den Josadak. Josadak aber ist fortgezogen, als der Herr Juda und Jerusalem durch Nebukadrezar wegführen ließ.',
    },
    6: {
        1: 'Levis Söhne sind Gersom, Kehat und Merari.',
        2: 'Dies sind die Namen der Söhne Gersoms: Libni und Simi.',
        3: 'Kehats Söhne sind Amram, Ishar, Chebron und Uzziel.',
        4: 'Meraris Söhne sind Machli und Musi. Dies sind die Sippen der Leviten nach ihren Familien:',
        5: 'Von Gersom stammt sein Sohn Libni, dessen Sohn Jachat, dessen Sohn Zimma,',
        6: 'dessen Sohn Joach, dessen Sohn Iddo, dessen Sohn Zerach und dessen Sohn Jeatrai.',
        7: 'Kehats Söhne sind sein Sohn Amminadab, dessen Sohn Korach, dessen Sohn Assir,',
        8: 'dessen Sohn Elkana, dessen Sohn Abjasaph, dessen Sohn Assir,',
        9: 'dessen Sohn Tachat, dessen Sohn Uriel, dessen Sohn Uzzia und dessen Sohn Saul.',
        10: 'Elkanas Söhne sind Amasai und Achimot,',
        11: 'dessen Sohn Elkana. Elkanas Söhne sind sein Sohn Sophai, dessen Sohn Nachat,',
        12: 'dessen Sohn Eliab, dessen Sohn Jerocham, dessen Sohn Elkana und dessen Sohn Samuel.',
        13: 'Samuels Söhne sind der Erstgeborene Joel und der zweite Abia.',
        14: 'Meraris Söhne sind Machli, dessen Sohn Libni, dessen Sohn Simei, dessen Sohn Uzza,',
        15: 'dessen Sohn Simea, dessen Sohn Chaggia und dessen Sohn Asaja.',
        16: 'Diese sind es, die David für den Gesang in des Herrn Haus bestellt hat, nachdem die Lade einen Ruheort gefunden hatte.',
        17: 'Sie hatten den Dienst im Gesang vor der Wohnung des Bundeszeltes, bis Salomo das Haus des Herrn zu Jerusalem baute. Und sie taten ihren Dienst nach ihrer Vorschrift.',
        18: 'Diese amteten samt ihren Söhnen: von den Söhnen der Kehatiter der Sänger Heman, Joels Sohn und Enkel Samuels,',
        19: 'des Sohnes Elkanas und Enkels Jerochams, des Sohnes Eliabs und Enkels Tochis,',
        20: 'des Sohnes Suphs und Enkels Elkanas des Sohnes Machats und Enkels Amasais,',
        21: 'des Sohnes Elkanas und Enkels Joels, des Sohnes Azajas und Enkels Sephanjas,',
        22: 'des Sohnes Tachats und Enkels Assirs, des Sohnes Ebjasaphs und Enkels Korachs,',
        23: 'des Sohnes Ishars und Enkels Kehats, des Sohnes Levis und Enkels Israels.',
        24: 'Sein Bruder ist Asaph, sein erster Gehilfe. Asaph, Berekjas Sohn und Enkel Simeas,',
        25: 'des Sohnes Mikaels und Enkels Baasejas, des Sohnes Malkias,',
        26: 'des Sohnes Etnis und Enkels Zerachs, des Sohnes Adajas,',
        27: 'des Sohnes Etans und Enkels Zimmas, des Sohnes Simis,',
        28: 'des Sohnes Jochats und Enkels Gersoms, des Levisohnes.',
        29: 'Meraris Söhne, ihre Brüder, waren ihre zweiten Gehilfen. Etan, Kisis Sohn und Enkel Abdis, des Sohnes Malluks,',
        30: 'des Sohnes Chasabjas und Enkels Amasjas, des Sohnes Chilkias,',
        31: 'des Sohnes Amsis und Enkels Banis, des Sohnes Semers,',
        32: 'des Sohnes Machlis und Enkels Musis, des Sohnes Meraris und Enkels Levis.',
        33: 'Ihre Brüder, die Leviten, waren für den ganzen Dienst an der Wohnung des Gotteshauses bestellt.',
        34: 'Aaron aber und seine Söhne räucherten an dem Brandopferaltar und an dem Räucheraltar, ebenso bei allen Diensten am Allerheiligsten und bei der Entsühnung Israels, genau nach der Vorschrift, die der Diener Gottes, Moses, gegeben hatte.',
        35: 'Dies sind Aarons Söhne: sein Sohn Eleazar, dessen Sohn Pinechas, dessen Sohn Abisu,',
        36: 'dessen Sohn Bukki, dessen Sohn Uzzi, dessen Sohn Zerachja,',
        37: 'dessen Sohn Merajot, dessen Sohn Amarja, dessen Sohn Achitub,',
        38: 'dessen Sohn Sadok und dessen Sohn Achimaas.',
        39: 'Dies sind ihre Wohnsitze nach ihren Zeltlagern in ihrem Gebiet: Den Aaronssöhnen, der Kehatitersippe - denn auf sie fiel das Los -,',
        40: 'gab man im Lande Juda Hebron und seine Weidetriften ringsumher.',
        41: 'Das Feld der Stadt aber und ihre Gehöfte hatte man Jephunnes Sohn Kaleb gegeben.',
        42: 'Den Aaronssöhnen aber hatte man die Zufluchtsstädte Hebron und Libna samt ihren Weidetriften übergeben, ferner Jattir und Estemoa mit den Ihrigen,',
        43: 'Cholon mit seinen Weidetriften, Debir,',
        44: 'Asan und Betsemes je mit seinen Weidetriften.',
        45: 'Vom Stamme Benjamin: Geba mit seinen Weidetriften und Anatot mit den seinigen. Die Gesamtzahl ihrer Städte ist dreizehn samt ihren Familien,',
        46: 'Die übrigen Kehatsstädte erhielten von den Sippen des Stammes Ephraim, vom Stamme Dan und vom Halbstamme Manasse zehn Städte durch das Los.',
        47: 'Gersoms Söhne erhielten nach ihren Sippen vom Stamme Issakar, vom Stamme Asser, vom Stamme Naphtali und vom Manassestamme in Basan dreizehn Städte.',
        48: 'Meraris Söhne erhielten nach ihren Sippen vom Stamme Ruben, vom Stamme Gad und vom Stamme Zabulon zwölf Städte durch das Los.',
        49: 'So gaben die Israeliten den Leviten die Städte samt den Weidetriften.',
        50: 'Man gab durchs Los vom Stamme der Judasöhne, von dem der Simeonsöhne und dem der Söhne Benjamins jene Städte, die namentlich genannt sind.',
        51: 'Bei den Sippen der Kehatssöhne rühren die Städte ihres Loses vom Stamm Ephraim her.',
        52: 'Man gab ihnen die Zufluchtsstädte Sichem mit seinen Weidetriften auf dem Gebirge Ephraim, Gezer mit den seinigen,',
        53: 'Jokmeam, Bet Choron,',
        54: 'Ajjalon und Gat Rimmon je mit ihren Weidetriften.',
        55: 'Und vom Halbstamm Manasse Aner mit seinen Weidetriften und Bileam mit den seinigen, und zwar den Sippen der übrigen Kehatssöhne.',
        56: 'Gersoms Söhne erhielten von der Sippe des Halbstammes Manasse in Basan Golan mit seinen Weidetriften und Astarot mit den Ihrigen',
        57: 'und vom Stamme Issakar Kedes mit seinen Weidetriften, Dobrat,',
        58: 'Ramot und Anem je mit ihren Weidetriften',
        59: 'und vom Stamme Asser Masal mit seinen Weidetriften, Abdon,',
        60: 'Chukok und Rechob je mit den Ihrigen,',
        61: 'und vom Stamme Naphtali in Galiläa Kedes mit seinen Weidetriften und Chammon und Kirjatim je mit den seinigen.',
        62: 'Die übrigen Merarisöhne erhielten vom Stamme Zabulon Rimmon und Tabor je mit ihren Weidetriften,',
        63: 'und jenseits des Jordans östlich vom Jordan, vom Stamme Ruben in der Steppe Beser mit seinen Weidetriften Ichsa,',
        64: 'Kedemot und Mephaat je mit den Ihrigen',
        65: 'und vom Stamme Gad in Gilead Ramot, Machanaim,',
        66: 'Chesbon und Jazer je mit ihren Weidetriften.',
    },
    7: {
        1: 'Zu den Söhnen Issakars gehören Tola und Pua, Jasub und Simron, vier.',
        2: 'Tolas Söhne sind Uzzi, Rephaja, Jeriel, Jachmai, Ibsam und Samuel, lauter Häupter in Tolas Familien, kriegstüchtige Männer nach ihren Sippen. Ihre Zahl war zu Davids Zeit 22.600.',
        3: 'Uzzis Söhne sind: Izrachja. Und IzrachjasSöhne sind Mikael, Obadja, Joel, Issia, fünf Häupter insgesamt.',
        4: 'Zu ihnen gehörten nach ihren Sippen, Familien und Kriegerscharen 36.000 Leute. Denn sie hatten viele Weiber und Kinder.',
        5: 'Und ihre Brüder, sämtliche Issakarsippen, waren kriegstüchtige Männer. Ihre Sippeliste umfaßte im ganzen 87.000 Mann.',
        6: 'Benjamins Söhne waren Bela, Beker und Jediael, drei.',
        7: 'Belas Söhne sind Esbon, Uzzi, Uzziel, Jerimot und Iri, fünf, lauter Familienoberhäupter, kriegstüchtige Männer. Ihre Sippenliste umfaßte 22.034 Mann.',
        8: 'Bekers Söhne sind Zemira, Joas, Eliezer, Eljoënai, Omri, Jerimot, Abia, Anatot und Alemet. Diese alle sind Söhne Bekers.',
        9: 'Ihre Sippenliste nach ihren Sippen, ihren Familienhäuptern und kriegstüchtigen Männern belief sich auf 20.200.',
        10: 'Jediaels Söhne sind: Bilhan. Und Bilhans Söhne sind Jëus, Benjamin, Ehud, Kenaana, Zetan, Tarsis und Achisachar.',
        11: 'Dies alle sind Jediaels Söhne, Familienhäupter, kriegstüchtige Leute, 17.200 zum Kampf Gerüstete.',
        12: 'Suppim und Chuppim sind Irs Söhne, Chusim sind Söhne des Acher.',
        13: 'Naphtalis Söhne sind Jachaziel, Guni, Jezer und Sallum, Bilhas Nachkommen.',
        14: 'Manasses Söhne sind: Asriel, den sein aramäisches Nebenweib gebar. Sie hat auch Gileads Vater, Makir, geboren.',
        15: 'Makir aber hatte für Chuppim und Suppim ein Weib genommen. Seine Schwester hieß Maaka. Der zweite aber hieß Selophchad. Selophchad aber hatte nur Töchter.',
        16: 'Makirs Weib aber gebar einen Sohn und nannte ihn Peres. Sein Bruder aber hieß Seres und dessen Söhne Ulam und Rekeni.',
        17: 'Ulams Söhne sind: Bedan. - Dies sind die Söhne Gileads, des Sohnes Makirs, des Manassesohnes.',
        18: 'Seine Schwester, die Königin, gebar Ishod, Abiezer und Machla.',
        19: 'Semidas Söhne sind Achjan, Sekem, Likchi und Aniam.',
        20: 'Ephraims Söhne sind Sutelach; dessen Sohn war Bered, dessen Sohn Tachat, dessen Sohn Elada, dessen Sohn Tachat,',
        21: 'dessen Sohn Zabad, dessen Sohn Sutelach sowie Ezer und Elad. - Die Männer von Gad aber haben sie, die im Lande geboren waren, getötet, weil sie zum Raub ihres Viehes hinabgezogen waren.',
        22: 'Da trauerte ihr Vater Ephraim viele Tage. Es kamen auch seine Brüder, ihn zu trösten.',
        23: 'Dann wohnte er seinem Weibe bei. Sie empfing und gebar einen Sohn. Er nannte ihn Beria, weil es geschehen war, als Unglück in seinem Hause war.',
        24: 'Seine Tochter aber war Seera. Sie baute das untere und obere Bet Horon, ebenso Uzzen Seera.',
        25: 'Sein Sohn war Rephach, ebenso Reseph; dessen Sohn war Telach, dessen Sohn Tachan,',
        26: 'dessen Sohn Ladan, dessen Sohn Ammihud, dessen Sohn Elisama,',
        27: 'dessen Sohn Nun und dessen Sohn Josue.',
        28: 'Ihr Besitz und ihre Wohnsitze sind Betel und dessen Tochterorte, nach Osten Naaran und nach Westen Gezer und Sichem je mit ihren Tochterorten bis gegen Gaza mit den zugehörigen Ortschaften.',
        29: 'Im Besitze der Manassesöhne sind Betsean mit seinen Tochterorten, Taanak, Megiddo und Dor mit je ihren Tochterorten. Darin wohnten die Söhne Josephs, des Sohnes Israels.',
        30: 'Assers Kinder sind Imna, Isva, Isvi und Beria mit ihrer Schwester Serach.',
        31: 'Berias Söhne sind Cheber und Malkiel, das ist der Vater von Bir Zait.',
        32: 'Cheber zeugte Iphlat, Somer und Chotam samt ihrer Schwester Sua.',
        33: 'Japhlets Söhne sind Pasak, Bimehal und Asvat. Dies sind die Söhne Japhlets.',
        34: 'Semers Söhne sind Achi, Rohga, Chubba und Aram.',
        35: 'Seines Bruders Helem Söhne sind Sophach, Imna, Seles und Amal.',
        36: 'Sophachs Söhne sind Suach, Charnepher, Sual, Beri, Imra,',
        37: 'Beser, Hod, Samma, Silsa, Itran und Beera.',
        38: 'Jeters Söhne sind Jephunne, Pispa und Ara.',
        39: 'Ullas Söhne sind Arach, Channiel und Risja.',
        40: 'Alle diese sind Assers Söhne, auserlesene kriegstüchtige Männer, Häupter der Fürsten. Man verzeichnete sie in den Listen für den Kriegsdienst, und ihre Zahl war 26.000 Mann.',
    },
    8: {
        1: 'Benjamin zeugte als seinen Erstgeborenen Bela, als zweiten Asbel, als dritten Achrach,',
        2: 'als vierten Nocha und als fünften Rapha.',
        3: 'Bela hatte zu Söhnen Addar, Gera, Abihud,',
        4: 'Abisu, Naaman, Achoch,',
        5: 'Gera, Sephuphan und Churam.',
        6: 'Dies sind Achuds Söhne. Diese sind die Familienhäupter der Einwohner Gebas. Man führte sie gefangen nach Manachat.',
        7: 'Naaman, Achia und Gera hat er fortgeführt, nachdem jener Uzza und Achichud gezeugt hatte.',
        8: 'Sacharaim zeugte in Moabs Gefilde, nachdem er seine Weiber Chusim und Baara entlassen hatte.',
        9: 'Er zeugte mit seinem Weibe Chodes den Jobab, Sibja, Mesa, Malkam,',
        10: 'Jëus, Sokja und Mirma. Dies sind seine Söhne, Familienhäupter.',
        11: 'Mit Chusim hatte er Abitub und Elpaal gezeugt.',
        12: 'Elpaals Söhne sind Eber, Misam und Semer. Dieser baute Ono, ebenso Lod mit seinen Tochterorten.',
        13: 'Beria und Sema sind die Familienhäupter der Einwohner Ajjalons. Sie haben die Bewohner von Gat vertrieben.',
        14: 'Berias Söhne sind Achjo, Sasak, Jeremot,',
        15: 'Zebadja, Arad, Ader,',
        16: 'Mikael, Ispa und Jocha.',
        17: 'Elpaals Söhne sind Zebadja, Mesullam, Chizki, Cheber,',
        18: 'Ismere, Izlia und Jobab.',
        19: 'Simeis Söhne sind Jakim, Zikri, Zabdi,',
        20: 'Elienai, Silletai, Eliel,',
        21: 'Adaja, Beraja und Simrat.',
        22: 'Sasaks Söhne sind Ispan, Eber, Eliel,',
        23: 'Abdon, Zikri, Chanan,',
        24: 'Chananja, Elam, Antotia,',
        25: 'lphdaja und Penuel.',
        26: 'Jerochams Söhne sind Samserai, Secharja, Atalja,',
        27: 'Jaaresja, Elia und Zikri.',
        28: 'Dies sind in ihren Sippen die Familienhäupter. Als Häupter haben sie zu Jerusalem gewohnt.',
        29: 'Zu Gibeon wohnten der Vater Gibeons und sein Weib namens Maaka.',
        30: 'Sein erstgeborener Sohn ist Abdon, dann Sur, Kis, Baal, Nadab,',
        31: 'Gedor, Achjo und Zeker.',
        32: 'Miklot hat Sima gezeugt. Auch sie wohnten in Jerusalem bei ihren Brüdern, diesen gegenüber.',
        33: 'Ner zeugte Kis und Kis den Saul und Saul den Jonatan, Malkisua, Abinadab und Esbaal.',
        34: 'Jonatans Sohn ist Meribbaal, und Meribbaal zeugte Mika.',
        35: 'Mikas Söhne sind Piton, Melek, Tare und Achaz.',
        36: 'Achaz zeugte Joadda und Joadda den Alemet, Azmavet und Zimri und Zimri den Mosa.',
        37: 'Mosa zeugte den Bina. Dessen Sohn ist Rapha, dessen Sohn Elasa und dessen Sohn Asel.',
        38: 'Asel hatte sechs Söhne. Dies sind ihre Namen: Azrikam, sein Erstgeborener, Ismael und Searja, Obadja und Chanan. Alle diese waren Söhne Asels.',
        39: 'Seines Bruders Esek Söhne sind sein Erstgeborener Ulam, der zweite Jëus und der dritte Eliphelet.',
        40: 'Ulams Söhne waren kriegstüchtige Männer, die den Bogen spannen konnten. Sie hatten auch zahlreiche Söhne und Enkel, 150. Alle diese gehören zu den Söhnen Benjamins.',
    },
    9: {
        1: 'Alle Israeliten sind in den Sippenlisten eingetragen worden. Und sie sind im Buch der Könige Israels aufgezeichnet. Die Judäer sind wegen ihrer Frevel nach Babel fortgeführt worden.',
        2: 'Die früheren Einwohner aber, die wieder auf ihrem Eigentum in ihren Städten lebten, waren Israeliten, die Priester, die Leviten und die Tempeldiener.',
        3: 'In Jerusalem haben von den Söhnen Judas Benjamins, Ephraims und Manasses gewohnt:',
        4: 'Utai, Ammihuds Sohn und Enkel Omris, des Sohnes Imris und Enkels Banis, von des Judasohnes Peres Nachkommen.',
        5: 'Von den Siloniten der Erstgeborene Asaja samt seinen Söhnen.',
        6: 'Von Zerachs Söhnen Jeuel samt ihren Brüdern, 690.',
        7: 'Von Benjamins Söhnen Sallu, des Mesullam Sohn und Enkel Hodavjas, des Sohnes Hassenas,',
        8: 'ferner Jerochams Sohn Ibneja und Ela, Uzzis Sohn und Enkel Mikris, und Mesullam, Sephatjas Sohn und Enkel Reuels, des Ibniasohnes,',
        9: 'samt ihren Brüdern nach ihren Geschlechtern, 956. Alle diese Männer sind in ihren Familien Familienhäupter.',
        10: 'Von den Priestern sind es Jedaja, Jojarib, Jakin',
        11: 'und Azarja, der Sohn des Chilkia und Enkel Mesullams, des Sohnes Sadoks und Enkels des Merajot, des Achitubsohnes, des Fürsten am Gotteshaus,',
        12: 'und Adaja, Jerochams Sohn und Enkel des Paschur, des Malkiasohnes, und Masai, Adiels Sohn und Enkel des Jachzera, des Sohnes Mesullams und Enkels Mesillemits, des Immersohnes,',
        13: 'und ihre Brüder, Häupter in ihren Familien, 1.760, Vorgesetzte der Schar, die den Dienst im Gotteshaus tut.',
        14: 'Von den Leviten sind es Semaja, des Chassub Sohn und Enkel Azrikams, des Sohnes Chasabjas, von den Merarisöhnen,',
        15: 'und Bakbakkar, Cheres, Galal, Makamja, des Mika Sohn und Enkel des Asaphsohnes Zikri,',
        16: 'Obadja, des Semaja Sohn und Enkel des Jedutunsohnes Galal, und Berekja, des Asa Sohn und Enkel des Elkana, der in den Netophatiterdörfern wohnt.',
        17: 'Ferner die Torhüter Sallum, Akkub, Talmon und Achiman, sowie ihre Brüder. Sallum ist der Oberste.',
        18: 'Bis heute sind am Königstore gegen Osten die Torhüter in den Lagern der Levisöhne.',
        19: 'Sallum, Kores Sohn und Enkel des Korachsohnes Ebjasaph, und seine Brüder aus seiner Familie, die Korachiter, liegen dem Dienste ob; sie hüten im Zelt die Schwellen. Schon ihre Väter sind im Lager des Herrn die Hüter des Eingangs gewesen.',
        20: 'Vor Zeiten ist Fürst über sie Eleazars Sohn Pinechas gewesen. Der Herr sei mit ihm!',
        21: 'Zakarja, Meselemjas Sohn, ist am Bundeszelte Torhüter.',
        22: 'Sie alle, die zu Torhütern an den Schwellen auserlesen sind, zählen 212. Sie sind in ihren Dörfern aufgezeichnet. David und der Seher Samuel haben sie in ihre Amtspflicht eingesetzt.',
        23: 'Sie, wie auch ihre Söhne, stehen an den Toren im Hause des Herrn, im Zelthaus, auf Wache.',
        24: 'Nach den vier Winden stehen die Torhüter gegen Osten, Westen, Norden, Süden.',
        25: 'Ihre Brüder in ihren Dörfern haben jeweils für sieben Tage zu kommen, sie zu unterstützen.',
        26: 'Denn die vier Obersten der Torhüter stehen in steter Dienstpflicht. Dies sind die Leviten. Sie beaufsichtigen auch die Zellen und Vorratskammern im Gotteshaus.',
        27: 'Sie bleiben in der Umgebung des Gotteshauses über Nacht. Denn ihnen liegt die Wache ob, und sie haben jeden Morgen aufzuschließen.',
        28: 'Und ein Teil von ihnen beaufsichtigt die Dienstgeräte. Denn sie bringen diese abgezählt hinein und hinaus.',
        29: 'Ein anderer Teil von ihnen ist über die Güter bestellt, und zwar über die heiligsten Güter, über das Feinmehl, den Wein, das Öl, den Weihrauch und die Spezereien.',
        30: 'Einige der Priestersöhne haben aus den Spezereien Salben zu mischen.',
        31: 'Einer der Leviten, Mattitja, des Korachiten Sallum Erstgeborener, ist mit dem Pfannenbackwerk betraut.',
        32: 'Etliche der Kehatitersöhne, ihrer Brüder, sind für die reihenweise gelegten Brote bestellt, die sie Sabbat um Sabbat bereiten.',
        33: 'Das sind die Sänger, levitische Familienhäupter, die nur in den Zellen dienstfrei sind. Denn sie haben sonst Tag und Nacht Dienst.',
        34: 'Dies sind levitische Familienhäupter, auch nach ihren Sippen Häupter. Diese wohnten zu Jerusalem.',
        35: 'Zu Gibeon wohnte Jeiel, Gibeons Vater. Sein Weib heißt Maaka.',
        36: 'Sein erstgeborener Sohn ist Abdon, ferner Sur, Kis, Baal, Ner, Nadab,',
        37: 'Gedor, Achjo, Zakarja und Miklot.',
        38: 'Miklot hat Simam gezeugt. Auch sie wohnten zu Jerusalem bei ihren Brüdern, diesen gegenüber.',
        39: 'Ner hat Kis gezeugt, Kis den Saul, Saul den Jonatan, Malkisua, Abinadab und Esbaal.',
        40: 'Jonatans Sohn ist Meribbaal, und Meribbaal hat Mika gezeugt.',
        41: 'Mikas Söhne sind Piton, Melek und Tachre.',
        42: 'Achaz hat Jara gezeugt und Jara den Alemet, Azmawet und Zimri. Zimri hat Mosa gezeugt',
        43: 'und Mosa den Bina. Sein Sohn ist Rephaja, dessen Sohn Elasa und dessen Sohn Asel.',
        44: 'Asel hat sechs Söhne. Dies sind ihre Namen: Azrikam, Bokru, Ismael, Searja, Obadja und Chanan. Dies sind Asels Söhne.',
    },
    10: {
        1: 'Die Philister aber kämpften mit Israel. Da floh Israels Mannschaft vor den Philistern, und Erschlagene lagen auf dem Gebirge Gilboa.',
        2: 'Und die Philister hefteten sich an Saul und seine Söhne. Und so erschlugen die Philister Sauls Söhne, Jonatan, Abinadab und Malkisua.',
        3: 'So wurde der Kampf für Saul immer schwerer. Da trafen ihn die Bogenschützen in den Leib. So wurde er durch die Bogenschützen verwundet.',
        4: 'Da sprach Saul zu seinem Waffenträger: "Zücke dein Schwert und erstich mich damit, daß nicht diese Unbeschnittenen kommen und mit mir ihr Spiel treiben!" Aber sein Waffenträger wollte nicht. Denn er scheute sich zu sehr. Da zog Saul selbst das Schwert und stürzte sich hinein.',
        5: 'Wie aber sein Waffenträger sah, daß Saul tot war, stürzte auch er sich in das Schwert und starb.',
        6: 'So starben Saul und seine drei Söhne und sein ganzes Haus; so starben sie miteinander.',
        7: 'Als aber Israels gesamte Mannschaft, die im Tale wohnte, sah, daß jene geflohen und daß Saul und seine Söhne tot waren, verließ sie ihre Städte und floh. Da kamen die Philister und siedelten darin.',
        8: 'Am anderen Morgen kamen die Philister, um die Erschlagenen zu plündern. Da fanden sie Saul und seine Söhne auf dem Gebirge Gilboa liegen.',
        9: 'Sie zogen ihn aus, nahmen sein Haupt und seine Waffen und sandten sie im Philisterlande umher, ihren Götzen und dem Volke die Siegesbotschaft zu künden.',
        10: 'Seine Waffen legten sie in dem Hause ihres Gottes nieder. Seinen Schädel aber nagelten sie im Hause Dagons an.',
        11: 'Als ganz Jabes in Gilead das alles hörte, was die Philister an Saul getan hatten,',
        12: 'machten sich alle wehrfesten Männer auf und holten Sauls Leichnam und die Leichen seiner Söhne und brachten sie nach Jabes. Sie begruben ihre Gebeine unter der Terebinthe zu Jabes und fasteten sieben Tage.',
        13: 'So starb Saul wegen seines Abfalls vom Herrn, wegen des Herrnwortes, das er nicht befolgt und auch, weil er einen Totengeist befragt',
        14: 'und nicht beim Herrn angefragt hatte. So ließ er ihn sterben und wandte das Königtum dem Isaisohne David zu.',
    },
    11: {
        1: 'Nun sammelte sich ganz Israel bei David zu Hebron und sprach: "Wir sind dein Fleisch und Bein.',
        2: 'Noch als Saul König war, bist du es gewesen, der Israel ins Feld und heimgeführt hat. Auch sprach der Herr, dein Gott, zu dir: \'Du sollst mein Volk Israel weiden und Fürst über mein Volk Israel sein!\'"',
        3: 'Also kamen alle Ältesten Israels zum König nach Hebron. Und David schloß mit ihnen zu Hebron vor dem Herrn einen Bund. Dann salbten sie David zum König über Israel nach dem Worte des Herrn durch Samuel.',
        4: 'Nun zog David mit ganz Israel gegen Jerusalem, das ist Jebus. Dort waren die Jebusiter einheimisch im Lande.',
        5: 'Da sprachen die Einwohner von Jebus zu David: "Du kommst nicht hier herein." David aber erstürmte die Burg Sions, das ist die Davidsstadt.',
        6: 'Da sprach David: "Jeder, der zuerst einen Jebusiter erschlägt, sei Hauptmann und Befehlshaber!" Da stieg Joab, der Sohn der Zeruja, zuerst hinauf. So ward er Hauptmann.',
        7: 'Hierauf ließ sich David in der Burg nieder. Darum nannte man sie Davidsstadt.',
        8: 'Er baute die Stadt ringsum, von der Bastei bis zu der Ringmauer. Und Joab stellte die übrige Stadt her.',
        9: 'David aber ward immer größer, und der Herr der Heerscharen war mit ihm.',
        10: 'Dies sind der Helden Davids Häupter, die fest zu ihm hielten, als er König ward, um ihn nach des Herrn Wort zum König auch über Gesamtisrael zu machen.',
        11: 'Dies ist die Zahl der Davidshelden: Chaknonis Sohn Josebeam, das Haupt der Dreißig. Er ist es, der seinen Speer über dreihundert Erschlagene auf einmal schwang.',
        12: 'Nach ihm kommt der Achotiter Eleazar, Dodos Sohn. Er gehörte zu den drei Helden.',
        13: 'Er war mit David am Blutsteinfelsen gewesen, als sich die Philister dort zur Schlacht sammelten. Nun war dort ein Feld voll Gerste. Als aber das Volk vor den Philistern floh,',
        14: 'stellten sie sich mitten auf das Feldstück, behaupteten es und schlugen die Philister, und der Herr verhalf ihnen zu einem großen Sieg.',
        15: 'Drei von den dreißig Hauptleuten stiegen nach dem Felsennest zu David, in die Höhle von Adullam hinab. Das Philisterheer aber lagerte in der Rephaimebene.',
        16: 'Damals war David in der Feste, die Philisterbesatzung aber in Bethlehem.',
        17: 'Nun spürte David ein Gelüste und fragte: "Wer holt mir Trinkwasser aus dem Brunnen in Bethlehem am Tore?"',
        18: 'Da schlugen sich die Drei durch das Philisterlager, schöpften Wasser aus dem Brunnen in Bethlehem am Tore und brachten es David. David aber wollte es nicht mehr trinken, sondern spendete es für den Herrn.',
        19: 'Er sprach: "Bewahre mich mein Gott davor, daß ich so etwas tue! Sollte ich dieser Männer Blut samt ihrem Leben trinken? Denn mit Lebensgefahr haben sie es hergebracht." Und so wollte er es nicht trinken. Solches taten die drei Helden.',
        20: 'Joabs Bruder Abisai war das Haupt der Dreißig. Er war es, der seinen Speer gegen dreihundert Unreine schwang. Bei den Dreien war er angesehen.',
        21: 'Er wurde schnell von den Dreien ausgezeichnet, und so ward er bei ihnen Hauptmann. Aber an die Drei reichte er nicht heran.',
        22: 'Benaja, Jojadas Sohn, war der Sohn eines tüchtigen, tatenreichen Mannes aus Kabseel, ein tapferer Held. Er selber hatte Moabs beide Kämpen erschlagen. Auch war er hinabgestiegen und hatte den Löwen mitten im Brunnen erschlagen, als Schnee fiel.',
        23: 'Er ist es auch, der den Ägypter, einen riesigen Mann von fünf Ellen, erschlagen hat. Der Ägypter hatte einen Speer gleich einem Weberbaume in der Hand. Er aber ging mit dem Stocke auf ihn los, entriß dem Ägypter die Lanze und tötete ihn mit dem eigenen Speere.',
        24: 'Solches hatte Benaja, Jojadas Sohn, getan. Und er war bei den Dreien angesehen.',
        25: 'Er hatte sich unter den Dreißig ausgezeichnet. Aber an die Drei reichte er nicht heran. David setzte ihn über seine Leibwache.',
        26: 'Die tapferen Helden sind Joabs Bruder Asael, der Bethlehemite Elchanan, Dodos Sohn,',
        27: 'der Haroditer Sammot, der Pelomiter Cheles,',
        28: 'der Tekoiter Ira, des Ikkes Sohn, der Anatotiter Abiezer,',
        29: 'der Chusatiter Sibkai, der Achotiter Ilai,',
        30: 'der Netophatiter Mocharai, der Netophatiter Cheled, Baanas Sohn,',
        31: 'Ribais Sohn Itai aus Gibea Benjamins, der Paratoniter Benaja,',
        32: 'Churai aus Nachale Gaas, der Asbatiter Abiel,',
        33: 'der Bacharumiter Azmavet, der Saalboniter Eljachba,',
        34: 'der Gizoniter Hasem, der Harariter Jonatan, des Sage Sohn,',
        35: 'der Harariter Achiam, Sakars Sohn, Eliphal, Urs Sohn,',
        36: 'der Mekeratiter Chepher, der Peloniter Achia,',
        37: 'der Karmeliter Chesro, Naarai, Ezbais Sohn,',
        38: 'Joel, Natans Bruder, Mibchar, Chagris Sohn,',
        39: 'der Ammoniter Selek, der Berotiter Nachrai, des Serujasohnes Joab Waffenträger,',
        40: 'der Istriter Ira, der Istriter Gareb,',
        41: 'der Chittiter Uria, Zobad, Achlais Sohn,',
        42: 'der Rubenite Adina, Zizas Sohn, ein Häuptling der Rubeniter und Anführer der Dreißig,',
        43: 'Chanan, Maakas Sohn, der Mitniter Josaphat,',
        44: 'der Astarotiter Uzzia, Sama und Jeiel, die Söhne des Aroëriters Chotam,',
        45: 'Jediael, Simris Sohn, und sein Bruder Jocha, der Tisiter,',
        46: 'der Machanatiter Eliel, Jeribai und Josavja, Elnaams Söhne, der Moabiter Itma,',
        47: 'Eliel, Obed und der Mesobaiter Jaasiel.',
    },
    12: {
        1: 'Dies sind die, die zu David nach Siklag kamen, als er von dem Kissohne Saul verjagt war. Auch sie gehörten zu den Helden, als Helfer im Kampfe,',
        2: 'bogenbewaffnet, geschickt, mit der Rechten und Linken Steine und Pfeile mit dem Bogen zu schleudern. Von den Benjaminiten, Sauls Brüdern,',
        3: 'der Hauptmann Achiezer und Joas, des Gibeatiters Semaa Söhne, ferner Jeziel und Pelet, Azmavets Söhne, Beraka und der Anatotiter Jehu,',
        4: 'der Gibeoniter Ismaja, ein Held unter den Dreißig und der Dreißig Anführer,',
        5: 'Jeremia, Jachaziel, Jochanan, der Gederatiter Jozabad,',
        6: 'Eluzai, Jerimot, Bealja, Semarja, der Chariphiter, Sephatja,',
        7: 'Elkana, Issia, Azarel, Joezer und Josbam, die Korachiter,',
        8: 'und Joela und Zebadja, Jerochams Söhne aus Gedor.',
        9: 'Auch von den Gaditen gingen tapfere Männer zu David auf die Feste in der Wüste, kampfgerüstete Krieger, die Schild und Lanze führten, wie Löwen anzusehen und schnellfüßig wie Gazellen auf den Bergen:',
        10: 'Ezer, der Hauptmann Obadia, der zweite, Eliab, der dritte,',
        11: 'Mismatina, der vierte, Jerema, der fünfte,',
        12: 'Attai, der sechste, Eliel, der siebte,',
        13: 'Isanan, der achte, Elzabad, der neunte,',
        14: 'Jeremia, der zehnte, Makbannai, der elfte.',
        15: 'Diese sind aus Gads Söhnen die Heerführer. Der geringste nahm es mit hundert und der größte mit tausend auf.',
        16: 'Diese waren es, die den Jordan im ersten Monat überschritten, als er durch alle seine Nebenzuflüsse voll war. Und sie durchzogen alle Täler in Ost und West.',
        17: 'Etliche kamen selbst von Benjamin und Juda zur Feste Davids.',
        18: 'Da ging David zu ihnen hinaus und sprach sie an: "Kommt ihr zu mir in Frieden, mir beizustehen, dann vereinige ich mich von Herzen mit euch. Kommt ihr aber, mich an meine Feinde zu verraten, obschon kein Unrecht an meinen Händen klebt, so sehe unserer Väter Gott darein und räche es!"',
        19: 'Da hatte ein Geist den Obersten der Drei eingehüllt, Amasai. Er sprach: "Dir, David, und deinem Volke, Isaisohn, sei Heil! Dir sei Heil und deinen Helfern! Denn dein Gott hilft dir." Da nahm sie David auf und machte sie zu Hauptleuten der Kriegerschar.',
        20: 'Auch von Manasse gingen etliche zu David über, als er mit den Philistern gegen Saul in den Kampf zog. Aber diesen half er nicht. Denn die Philisterfürsten hatten ihn absichtlich fortgeschickt; sie sagten: "Er kann mit unseren Köpfen zu seinem Herrn Saul übergehen."',
        21: 'Als er nach Siklag zog, gingen von Manasse zu ihm über: Adnach, Jozabad, Jediael, Mikael, Jozabad, Elihu und Silletai, die Häupter der Tausend Manasses.',
        22: 'Diese halfen David bei der Kampfstellung. Denn sie waren alle tapfere Männer. Sie wurden auch Anführer im Heere.',
        23: 'Denn Tag für Tag kamen Leute zu David, ihm zu helfen, bis das Heer groß geworden war wie ein Gottesheer.',
        24: 'Dies ist die Zahl des Heerbannes, der zu David nach Hebron kam, um ihm Sauls Königtum nach des Herrn Befehl zu übertragen:',
        25: 'Judas Söhne, die Schild und Lanze trugen, 6.800 zum Kriegszug Gerüstete,',
        26: 'von den Simeonsöhnen 7.100 tapfere Kriegsleute,',
        27: 'Von den Levisöhnen 4.600',
        28: 'samt dem Aaronsfürsten Jojada, bei dem 3.700 waren,',
        29: 'und samt Sadok, einem tapferen Jüngling, dessen Familie zweiundzwanzig Anführer stellte.',
        30: 'Von den Söhnen Benjamins, Sauls Brüdern, 3.000. Bis dahin hatte die Mehrzahl von ihnen den Wachdienst für Sauls Haus gestellt.',
        31: 'Von den Söhnen Ephraims 20.800 tapfere, in ihren Familien hochangesehene Männer.',
        32: 'Vom Halbstamme Manasse 18.000, die namentlich bezeichnet waren, hinzugeben und David zum König zu machen.',
        33: 'Von den Söhnen Issakars, die Einsicht in die Zeitläufte hatten, so daß sie wußten, was Israel tun sollte, 200 Hauptleute, samt allen ihren Brüdern unter ihrem Befehl.',
        34: 'Von Zabulon 50.000 Kriegstüchtige, mit allerlei kriegerischen Waffen ausgestattet; bereit, sich einzuordnen.',
        35: 'Von Naphtali 1.000 Anführer; sie hatten 37.000 Mann mit Schild und Speer bei sich.',
        36: 'Von den Daniten 28.600 Kampfgerüstete.',
        37: 'Von Asser 40.000 Kriegstüchtige, bereit, Krieg zu führen,',
        38: 'und von jenseits des Jordans, von den Rubeniten, den Gaditen und dem Halbstamme Manasse 120.000 mit allerlei Kriegswaffen.',
        39: 'Alle diese Kriegsleute, in Reihen geordnet, kamen einmütig nach Hebron, David zum König über ganz Israel zu machen. Auch das ganze übrige Israel war ungeteilten Herzens dabei, David zum König zu machen.',
        40: 'Sie blieben dort bei David drei Tage, aßen und tranken. Denn ihre Brüder hatten für sie zugerichtet. Auch die ihnen nahe wohnten, bis nach Issakar, Zabulon und Naphtali hin, brachten Brot auf Eseln, Kamelen Maultieren und Rindern, Mehlspeisen, Feigen und Rosinenkuchen, Wein, Öl, Rinder und Schafe in Menge; denn Jubel herrschte in Israel.',
    },
    13: {
        1: 'David beriet sich nun mit den Anführern der Tausendschaften und Hundertschaften von jedem Stamme.',
        2: 'Und David sprach zur Gesamtgemeinde Israels: "Ist es euch recht und wird es vom Herrn, unserem Gott, gebilligt, dann senden wir zu unseren Brüdern, die übrig sind in allen Landen Israels, und zu den Priestern und den Leviten in den Städten ihrer Weidebezirke, sie sollen sich bei uns versammeln.',
        3: 'Wir wollen unseres Gottes Lade zu uns holen. Denn in Sauls Tagen fragten wir nicht nach ihr."',
        4: 'Da sagte die ganze Gemeinde, man solle so tun. Denn die Sache gefiel dem ganzen Volk.',
        5: 'So berief David ganz Israel von Ägyptens Schichor bis Hamat, um die Gotteslade aus Kirjat Jearim zu holen.',
        6: 'Und David zog mit ganz Israel zur Burg, nach Kirjat Jearim, in Juda, von dort die Lade Gottes zu holen, des Herrn, der auf Cheruben thront, und wo man seinen Namen angerufen hatte.',
        7: 'Sie fuhren nun die Gotteslade, vom Hause Abinadabs an, auf einem neuen Wagen. Uzza und Achjo führten den Wagen.',
        8: 'David aber tanzte mit ganz Israel vor Gott unter dem Klange von Zithern, Harfen und Pauken, Zimbeln und Trompeten.',
        9: 'Wie sie aber an ein gepflegtes Feldstück kamen, streckte Uzza seine Hand aus, die Lade zu fassen, weil die Rinder sie ins Wanken gebracht hatten.',
        10: 'Da entbrannte des Herrn Zorn wider Uzza, und er schlug ihn, weil er seine Hand gegen die Lade ausgestreckt hatte. Und er starb dort vor Gott.',
        11: 'Da ward David mißgestimmt, daß der Herr Uzza geschlagen hatte. Und er nannte jenen Ort "Schlag des Uzza" bis auf diesen Tag.',
        12: 'David aber fürchtete sich vor Gott an jenem Tage und sprach: "Wie kann ich die Gotteslade zu mir bringen?"',
        13: 'So ließ David die Lade nicht zu sich in die Davidsstadt bringen, sondern beiseite in das Haus des Gatiters Obededom.',
        14: 'So blieb die Gotteslade drei Monate im Hause Obededoms, drei Monate in seinem Hause. Aber der Herr segnete Obededoms Haus und all seine Habe.',
    },
    14: {
        1: 'Chiram, der König von Tyrus, sandte nun an David Boten mit Zedernholz, dazu Steinmetzen und Zimmerleute, ihm ein Haus zu bauen.',
        2: 'Da erkannte David, daß ihn der Herr als König über Israel bestätigt hatte. Denn hochgeehrt ward sein Königtum wegen seines Volkes Israel.',
        3: 'David aber nahm noch weitere Frauen zu Jerusalem. Und David zeugte noch weitere Söhne und Töchter.',
        4: 'Dies sind die Namen der Kinder, die ihm zu Jerusalem geboren worden sind: Sammua, Sobab, Natan und Salomo,',
        5: 'Ibchar, Elisua, Elpelet,',
        6: 'Nogach, Nepheg, Japhia,',
        7: 'Elisama, Beeljada und Eliphelet.',
        8: 'Die Philister aber hörten, David sei zum König über ganz Israel gesalbt worden. Da zogen alle Philister hinauf, David zu suchen. David aber hörte es. Da zog er ihnen entgegen.',
        9: 'Die Philister kamen nun und ließen sich in der Rephaimebene nieder.',
        10: 'Da befragte David Gott: "Soll ich gegen die Philister ziehen? Gibst Du sie in meine Hand?" Da sprach der Herr zu ihm: "Zieh hin! Ich gebe sie in deine Hand."',
        11: 'Da zogen sie nach Baal Perasim hinauf. Und dort schlug sie David. Und David sprach: "Gott ist durch mich gegen meine Feinde durchgebrochen, wie Wasser durchbricht." Deshalb nannte man jenen Ort Baal Perasim.',
        12: 'Sie ließen dort ihre Götter im Stich, und David hieß sie verbrennen.',
        13: 'Die Philister kamen wieder und ließen sich in der Ebene nieder.',
        14: 'Da befragte David wiederum Gott, und Gott sprach zu ihm: "Du sollst nicht hinter ihnen hinaufziehen! Wende dich von ihnen ab und komme vom Rücken her über sie, von den Geröllhalden her!',
        15: 'Sobald du das Geräusch von Schritten auf den Rändern der Geröllhalden hörst, dann brich los! Denn dann zieht dir Gott voran, das Philisterheer zu schlagen."',
        16: 'David tat so, wie ihn Gott geheißen. Und sie schlugen das Philisterheer von Gibeon bis gegen Gezer.',
        17: 'Und Davids Ruhm verbreitete sich in allen Landen, hatte doch der Herr Angst vor ihm auf alle Völker gelegt.',
    },
    15: {
        1: 'Und David machte sich in der Davidsstadt Häuser; dann bereitete er eine Stätte für die Gotteslade und schlug für sie ein Zelt auf.',
        2: 'Damals bestimmte David, daß niemand außer den Leviten die Gotteslade trage. Denn diese hatte der Herr erwählt, die Gotteslade zu tragen und ihm stets zu dienen.',
        3: 'So berief David ganz Israel nach Jerusalem, des Herrn Lade an ihren Platz zu bringen, den er ihr bereitet hatte.',
        4: 'Und David versammelte die Aaronssöhne und die Leviten,',
        5: 'von den Söhnen Kehats den Obersten Uriel und seine 120 Brüder,',
        6: 'von den Merarisöhnen den Obersten Asaja und seine 220 Brüder,',
        7: 'von den Gersomsöhnen den Obersten Joel und seine 130 Brüder,',
        8: 'von den Elisaphansöhnen den Obersten Semaja und seine 200 Brüder,',
        9: 'von den Chebronsöhnen den Obersten Eliel und seine 80 Brüder,',
        10: 'von den Uzzielsöhnen den Obersten Amminadab und seine 112 Brüder.',
        11: 'Dann berief David die Priester Sadok und Ebjatar sowie die Leviten Uriel, Asaja, Joel, Semaja, Eliel und Amminadab.',
        12: 'Er sprach zu ihnen: "Ihr seid die Familienhäupter der Leviten. Heiligt euch und eure Brüder und bringt die Lade des Herrn, des Gottes Israels, an den Ort, den ich für sie bereitet habe!',
        13: 'Weil ihr das erstemal nicht zugegen gewesen seid, so hat der Herr, unser Gott, unter uns dreingeschlagen. Denn wir kümmerten uns nicht um ihn nach Gebühr."',
        14: 'Da heiligten sich die Priester und die Leviten, um die Lade des Herrn, des Gottes Israels, hinaufzuführen.',
        15: 'Und die Levisöhne trugen die Gotteslade mit den Tragstangen auf ihren Schultern, wie Moses nach des Herrn Wort befohlen hatte.',
        16: 'Hierauf befahl David den Obersten der Leviten, ihre Brüder, die Sänger, zu bestellen mit Musikinstrumenten, Harfen, Zithern und Zimbeln; sie sollten lauten Jubelschall ertönen lassen.',
        17: 'Da bestellten die Leviten Joels Sohn Heman und von seinen Brüdern Berekjas Sohn Asaph und von den Merarisöhnen, ihren Brüdern, den Etan, Kusajas Sohn,',
        18: 'und mit ihnen ihre Brüder, die zweiten Ranges waren, Zakarja, Jaaziel, Semiramot, Jechiel, Unni, Eliab, Benaja, Maaseja, Mattitja, Eliphelehu, Miknejahu, Obededom und Jeiel, die Torhüter.',
        19: 'Und die Sänger Heman, Asaph und Etan hatten mit ehernen Zimbeln laut zu spielen.',
        20: 'Zakarja aber, Aziel, Semiramot, Jechiel, Unni, Eliab, Maaseja und Benaja hatten mit Harfen die Führung,',
        21: 'und Mattitja, Eliphelehu, Miknejahu, Obededom, Jeiel und Azazja hatten mit Zithern Lieder zu singen.',
        22: 'Kenanja aber war der Oberste der Leviten im Tonangeben. Er sang auch beim Tonangeben. Denn er war kunstfertig.',
        23: 'Berikja und Elkana waren die Hüter der Lade.',
        24: 'Die Priester Sebanjahu, Josaphat, Netanel, Amasai, Zakarja, Benjahu und Eliezer bliesen vor der Gotteslade Trompeten. Hüter der Lade waren Obededom und Jechia.',
        25: 'David aber und die Ältesten Israels und die Obersten der Tausendschaften zogen hin, aus dem Hause Obededoms die Bundeslade des Herrn voller Freude hinaufzubringen.',
        26: 'Und Gott stand den Leviten bei, den Trägern der Bundeslade des Herrn. Sie opferten sieben Farren und sieben Widder.',
        27: 'David war mit einem Byssusmantel bekleidet, ebenso alle Leviten, die die Lade trugen, desgleichen die Sänger und Kenanja, der Oberste der Sänger im Tonangeben. David trug noch ein linnenes Ephod.',
        28: 'So brachte ganz Israel die Bundeslade des Herrn hinauf unter Jubel und lautem Posaunenschall, mit Trompeten und Zimbeln. Sie ließen Harfen und Zithern ertönen.',
        29: 'So kam des Herrn Bundeslade in die Davidsstadt. Sauls Tochter Mikal aber beugte sich durch das Fenster. Da sah sie den König hüpfen und tanzen. Und sie verachtete ihn in ihrem Herzen.',
    },
    16: {
        1: 'Sie aber brachten die Gotteslade hinein und stellten sie mitten in das Zelt, das David dafür ausgespannt hatte. Dann brachten sie vor Gott Brand- und Dankopfer dar.',
        2: 'Als nun David mit der Darbringung der Brand und Dankopfer fertig war, segnete er das Volk im Namen des Herrn.',
        3: 'Dann verteilte er an alle Israeliten, Männer wie Weiber, je einen Brotkuchen, einen Laib und einen Traubenkuchen.',
        4: 'Vor die Lade des Herrn aber bestellte er einige Leviten als Diener, daß sie den Herrn, Israels Gott, priesen, ihm dankten und ihn rühmten:',
        5: 'Asaph, das Oberhaupt, und Zakarja, den zweiten im Range nach ihm, sodann Jeiel, Semiramot, Jechiel, Mattitja, Eliab, Benajahu, Obededom und Jeiel mit Harfen und Zithern. Asaph aber sollte die Zimbeln ertönen lassen,',
        6: 'ebenso die Priester Benajahu und Zachaziel beständig die Trompeten vor der Bundeslade Gottes.',
        7: 'Damals übertrug David zuerst Asaph und seinen Brüdern den Lobpreis des Herrn:',
        8: '"Dem Herrn sagt Dank! Verherrlicht seinen Namen! Kund machet seine Taten den Nationen!',
        9: 'Lobsinget ihm! Lobt ihn! Erzählt von allen seinen Wundern!',
        10: 'In seinem heiligen Namen rühmet euch. Wer da den Herrn sucht, freue sich von Herzen!',
        11: 'Verlanget nach dem Herrn und seiner Herrlichkeit! Sein Antlitz suchet immerfort!',
        12: 'Gedenkt der Wunder all, die er gewirkt, der Zeichen, seiner Richtersprüche!',
        13: 'Du, seines Knechtes Israel Geschlecht, ihr Söhne Jakobs, seine Auserwählten!',
        14: 'Der Herr ist unser Gott, und auf der ganzen Erde gelten seine Urteile.',
        15: 'In Ewigkeit gedenkt er seines Bundes und seines Wortes, das er ausgesprochen, bis in das tausendste Geschlecht,',
        16: 'des Bundes, den er einst mit Abraham geschlossen, und seines Eides, den er Isaak zugeschworen,',
        17: 'den er für Jakob als ein Recht bestätigt, für Israel als ewigen Bund.',
        18: "Er sprach: 'Dir gebe ich der Kanaaniter Land als euer erblich Eigentum.'",
        19: 'Noch klein war damals ihre Zahl; sie waren wenige und fremd darin.',
        20: 'Sie wanderten von einem Heidenvolk zum anderen, von einem Reich zu einer anderen Nation.',
        21: 'Er hat niemand gestattet, sie zu drücken; er warnte ihretwegen Könige.',
        22: "'Vergreift euch nicht an den von mir Gesalbten! Nicht füget meinen Sehern Schaden zu!'",
        23: 'Dem Herrn lobsinge alle Welt! Sein Heil tut kund von Meer zu Meer!',
        24: 'Verkündet bei den Heiden seinen Ruhm, bei allen Völkern seine Wunder,',
        25: 'ist doch der Herr so groß und hoch zu preisen, vor allen Göttern ehrfurchtswert!',
        26: 'Der Völker Götter alle sind ja Götzen; des Himmels Schöpfer ist der Herr.',
        27: 'Vor ihn mit Glanz und Herrlichkeit! Mit Macht und Pracht zu seinem Heiligtum!',
        28: 'So bringt dem Herrn, ihr Völkerscharen, herbei bringt Pracht und Macht dem Herrn!',
        29: 'So bringt dem Herrn zu seines Namens Ehre Gaben! Betretet mit Geschenken seine Vorhöfe! Hinwerft euch vor dem Herrn mit Schmuck fürs Heiligtum!',
        30: 'Vor ihm erzittere alle Welt! Dann steht die Erde ohne Wanken.',
        31: "Der Himmel freue sich, die Erde jauchze; zurufen sollen sie den Heiden: 'Der Herr ist König!'",
        32: 'Es brause auf das Meer und seine Fülle; die Flur und alles, was darin, frohlocke!',
        33: 'Des Waldes Bäume sollen jubeln vor dem Herrn! Er kommt, die Erde jetzt zu richten.',
        34: 'So dankt dem Herrn! Denn er ist gütig. Ja, ewig währet seine Huld.',
        35: "Und sprecht: 'Hilf uns, Du unseres Heiles Gott, und sammle und befreie von den Heiden uns, auf daß wir Deinem heiligen Namen danken und Deines Lobpreises uns rühmen!",
        36: 'Gepriesen sei der Herr, Gott Israels, von Ewigkeit zu Ewigkeit!\'" - Und alles Volk sprach: "Amen" und einen Lobspruch auf den Herrn.',
        37: 'Dann übergab er dort vor der Bundeslade des Herrn dem Asaph mit seinen Brüdern für immer den Dienst, vor der Lade zu dienen, Tag für Tag nach Vorschrift,',
        38: 'ferner Obededom mit seinen achtundsechzig Brüdern und Jedituns Sohn, Obededom und Chosa als Torhüter,',
        39: 'ferner dem Priester Sadok und seinen Brüdern, den Priestern vor des Herrn Wohnung auf der Höhe von Gibeon,',
        40: 'dem Herrn auf dem Brandopferaltar regelmäßig jeden Morgen und Abend Brandopfer darzubringen, eben alles, was in der Lehre des Herrn, die er Israel gebot, geschrieben steht.',
        41: 'Bei ihnen waren Heman und Jedutun und die übrigen Auserlesenen, die mit Namen genannt sind, um den Herrn zu preisen, daß seine Gnade ewig währe.',
        42: 'Bei ihnen waren auch Trompeten und Zimbeln für die Musiker und die Spielgeräte für die Gotteslieder. Jedutuns Söhne waren für die Pforte da.',
        43: 'Darauf ging das ganze Volk heim, jeder in ein Haus. David aber wandte sich, sein Haus zu segnen.',
    },
    17: {
        1: 'David wohnte nun in seinem Hause. Da sprach David zum Propheten Natan: "Ich wohne in einem Zedernhause, des Herrn Bundeslade aber unter Zelttüchern."',
        2: 'Da sprach Natan zu David: "Tu alles, was du im Sinne hast! Denn Gott ist mit dir."',
        3: 'Aber noch in derselben Nacht erging Gottes Wort an Natan also:',
        4: '"Geh und sage meinem Knechte David: So spricht der Herr: Nicht du sollst mir das Haus zum Wohnen bauen!',
        5: 'Ich habe nie in einem Haus gewohnt seit jener Zeit, wo ich einst Israel heraufgeführt, bis hin zu diesem Tag. Ich zog von einem Wohngezelt zum anderen.',
        6: "So lange bin ich in ganz Israel herumgezogen. Habe ich ein Wort zu einem Richter Israels gesagt, die ich bestellt, mein Volk zu weiden: 'Warum baut ihr mir nicht ein Zedernhaus?'",
        7: 'So sage nunmehr meinem Knechte David: So spricht der Herr der Heeresscharen: Ich habe dich von der Weide aus der Herde hinweggeholt, auf daß du meines Volkes Israel Gebieter seiest.',
        8: 'Ich war mit dir allüberall, wohin du gingst, und tilgte vor dir alle deine Feinde. Ich habe einen Namen dir geschaffen, gleich dem der Großen auf der Erde.',
        9: 'Ich habe eine Stätte meinem Volke Israel bestimmt und es dann eingepflanzt, daß es, an seiner Stätte wohnend, nicht mehr zittere, und Ruchlose es nimmer drücken so wie früher.',
        10: 'Seit jenen Zeiten, da ich Richter meinem Volke Israel bestellt, demütigte ich alle deine Feinde. Nun künde ich dir an: "Der Herr baut dir ein Haus."',
        11: 'Sind deine Tage voll geworden, daß du zu deinen Vätern gehst, alsdann bestimme ich aus deinen Söhnen deinen Nachfolger und festige sein Königtum.',
        12: 'Mir baut er dann ein Haus, und ich befestige für alle Zeiten deinen Thron.',
        13: 'Ich will ihm Vater sein, er wird mir Sohn. Und ich entziehe nie ihm meine Huld, wie ich sie dem entzog, der vor dir war.',
        14: 'Und ich bestelle ihn für mein Haus und für mein Reich auf alle Zeit. Sein Thron hat immerdar Bestand."',
        15: 'Genau nach diesen Worten und nach diesem Gesicht redete Natan zu David.',
        16: 'Da ging der König David, setzte sich vor den Herrn und sprach: "Wer bin ich, Herr, Gott? Was ist mein Haus, daß Du mich bis hierher geführt?',
        17: 'Dies war Dir noch zuwenig, Gott. Du gabst dem Hause Deines Sklaven Verheißungen auf weit hinaus. Du siehst auf mich, Herr, Gott, als wäre ich gar eine hehre menschliche Gestalt.',
        18: 'Was soll denn David Dir noch weiter sagen von Deines Knechtes Ruhm? Du kennst ja selber Deinen Sklaven.',
        19: 'Für Deinen Sklaven, Herr, für Deinen Hund, hast Du das Große all getan und alle diese Herrlichkeiten angekündigt.',
        20: 'Herr! Dir ist keiner gleich. Kein Gott ist außer Dir nach alledem, was wir vernommen.',
        21: 'Wo ist ein Volk wie Dein Volk Israel, ein einzig Volk auf Erden, das sich zum Volke zu erkaufen ein Gott gegangen wäre, Dir einen Namen, groß und furchtbar, zu erwerben; daß Heiden Du vertriebst vor Deinem Volke, das Du aus dem Ägypterland erlöst?',
        22: 'Doch Du hast Israel, Dein Volk, für immer Dir zum Volk bestellt, und Du bist ihnen, Herr, zum Gott geworden.',
        23: 'Nun aber, Herr! Verwirkliche das Wort für immer, das über Deinen Sklaven und sein Haus Du hast gesprochen! Und tu jetzt, wie Du es gesagt!',
        24: "Dann ist Dein Name wohlbewährt und groß für immer, und er lautet: 'Der Herr der Heerscharen, Gott Israels, der Schutzgott Israels.' Und Deines Sklaven David Haus steht fest vor Dir.",
        25: 'Denn Du, mein Gott, hast Deinem Sklaven selbst geoffenbart, ein Haus ihm zu erbauen. Drum faßt Dein Sklave sich ein Herz, um dies Gebet Dir vorzutragen.',
        26: 'Nun, Herr, Du selbst bist Gott. Du gabst dies herrliche Versprechen Deinem Sklaven.',
        27: 'Nun laß es Dir gefallen und segne Deines Sklaven Haus, daß es für alle Zeit vor Dir bestehe! Denn was Du segnest, Herr, das ist für alle Zeit gesegnet."',
    },
    18: {
        1: 'Danach schlug David die Philister und demütigte sie. Er nahm Gat mit seinen Tochterorten den Philistern weg.',
        2: 'Dann schlug er Moab, und die Moabiter wurden David untertan und brachten Gaben.',
        3: 'Hierauf schlug David den König von Soba, Hadarezer, gegen Hamat zu, als er daranging, seine Macht am Euphratstrome aufzurichten.',
        4: 'David nahm ihm 1.000 Wagen, 7.000 Reiter und 20.000 Mann Fußvolk weg. Alle Rosse lähmte David. Nur 100 Rossewagen ließ er übrig.',
        5: 'Da kamen die damaszenischen Aramäer dem König von Soba, Hadarezer, zu Hilfe. Aber David schlug die Aramäer, 22.000 Mann.',
        6: 'Dann setzte David im damaszenischen Aram Vögte ein. So wurden die Aramäer David untertan und steuerpflichtig. Der Herr half David überall, wohin er zog.',
        7: 'David nahm auch die goldenen Schilde, die Hadarezers Knechte trugen, und brachte sie nach Jerusalem.',
        8: 'Aus Tibchat und Kun, Hadarezers Städten, holte David sehr viel Erz. Daraus machte Salomo das eherne Meer, die Säulen und die ehernen Geräte.',
        9: 'Da hörte Hamats König Tou, David habe die ganze Streitmacht Hadarezers, des Königs von Soba, geschlagen.',
        10: 'So sandte er nun seinen Sohn Hadoram zu König David, ihn zu begrüßen und zu beglückwünschen wegen seines siegreichen Kampfes mit Hadarezer. Denn Hadarezer war Tous Kriegsgegner. Er sandte auch allerlei goldene, silberne und eherne Gegenstände.',
        11: 'Auch sie weihte König David dem Herrn samt dem Silber und Gold, das er von den Heiden weggeführt hatte, von Edom, Moab, den Söhnen Ammons, den Philistern und den Amalekitern.',
        12: 'Serujas Sohn, Absai, aber hatte Edom, 18.000 Mann, im Salztal geschlagen.',
        13: 'Er setzte in Edom Vögte ein, und ganz Edom ward David untertan. Und der Herr half David überall, wohin er kam.',
        14: 'So regierte David ganz Israel und übte Recht und Gerechtigkeit an seinem ganzen Volk.',
        15: 'Joab, Serujas Sohn, war über das Heer gesetzt. Achiluds Sohn Josaphat war Kanzler,',
        16: 'Sadok, Achitubs Sohn, und Ebjatars Sohn Abimelek waren Priester und Savsa Schreiber.',
        17: 'Benjahu, Jojadas Sohn, befehligte die Bogenschützen und die Schildträger. Davids Söhne aber waren die Ersten um den König.',
    },
    19: {
        1: 'Danach starb der Ammoniterkönig Nachas, und sein Sohn ward König an seiner Statt.',
        2: 'Da sprach David: "Ich will dem Chanun, des Nachas Sohn, Liebes tun, weil sein Vater mir Liebes getan hat." So sandte David Boten, ihn wegen seines Vaters zu trösten. So kamen Davids Diener ins Ammoniterland zu Chanun, ihn zu trösten.',
        3: 'Da sprachen die Ammoniterfürsten zu Chanun: "Ehrt David nach deiner Ansicht deinen Vater, daß er dir Tröster schickt? Kommen seine Diener nicht zum Ausforschen, Erkunden und Ausspähen des Landes zu dir?"',
        4: 'Da ergriff Chanun die Diener Davids, schor sie und schnitt ihnen die Gewänder halb bis ans Gesäß ab. So schickte er sie fort.',
        5: 'Sie gingen. Nun berichtete man David über die Männer. Da sandte er ihnen entgegen. Denn die Männer waren schwer beschimpft. Der König ließ sagen: "Bleibt in Jericho, bis euch der Bart gewachsen ist! Dann kommt heim!"',
        6: 'Die Ammoniter aber merkten, daß sie sich bei David verhaßt gemacht hatten. Da schickten Chanun und die Ammoniter tausend Silbertalente, sich bei den Aramäern in Mesopotamien und den Aramäern von Maaka und Soba Wagen und Reiter zu dingen.',
        7: 'Sie dingten sich 32.000 Wagen sowie den König von Maaka mit seinem Volk. Dann zogen sie heran und lagerten vor Medeba. Auch die Ammoniter sammelten sich aus ihren Städten und zogen zum Kampf aus.',
        8: 'Als David dies hörte, schickte er Joab mit dem ganzen Heer der Krieger aus.',
        9: 'Da rückten die Ammoniter aus und stellten sich am Eingang der Stadt zum Kampfe auf. Die Könige aber, die gekommen waren, standen für sich im Gelände.',
        10: 'Als Joab sah, daß ihm ein Angriff von vorn und von hinten drohe, wählte er Leute aus allen Erlesenen Israels und stellte sich den Aramäern entgegen.',
        11: 'Den Rest des Volkes aber unterstellte er seinem Bruder Absai. Und sie stellten sich den Ammonitern gegenüber.',
        12: 'Er sprach: "Werden die Aramäer mir zu stark, dann komm du mir zu Hilfe! Sind aber die Ammoniter dir zu stark, dann helfe ich dir.',
        13: 'Sei tapfer! Seien wir mutig für unser Volk und die Diener unseres Gottes! Der Herr aber tue, was ihm gefällt!"',
        14: 'So rückte Joab mit dem Volke bei ihm zum Kampfe gegen die Aramäer vor. Da flohen sie vor ihm.',
        15: 'Als die Ammoniter sahen, daß die Aramäer flohen, flohen auch sie vor seinem Bruder Absai und zogen sich zurück. Hierauf zog Joab nach Jerusalem.',
        16: 'Als die Aramäer sahen, daß sie von Israel geschlagen waren, sandten sie Boten und ließen die Aramäer jenseits des Stromes ausrücken. Und Hadarezers Feldherr Sophak stand an ihrer Spitze.',
        17: 'Dies ward David gemeldet. Da bot er ganz Israel auf, überschritt den Jordan, zog gegen sie und stellte sich ihnen zum Kampf. David stellte sich also gegen die Aramäer zum Kampfe auf, und sie stritten mit ihm.',
        18: 'Aber die Aramäer mußten vor Israel fliehen, und David schlug von den Aramäern 7.000 Wagenkämpfer und 40.000 Mann Fußvolk. Auch den Feldherrn Sophak tötete er.',
        19: 'Als Hadarezers Diener sahen, daß sie von Israel geschlagen waren, schlossen sie Frieden mit David und waren ihm untertan. Und die Aramäer hatten keine Lust mehr, den Ammonitern weiter zu helfen.',
    },
    20: {
        1: 'Zur Zeit der Jahreswende, zur Zeit, wenn die Könige ins Feld ziehen, führte Joab das Heer ins Feld und verheerte das Ammoniterland. Dann zog er hin und belagerte Rabba. David aber blieb in Jerusalem. Dann erstürmte Joab Rabba und zerstörte es.',
        2: 'David aber nahm dem Milkom seine Krone vom Kopf und fand, daß sie ein Talent Gold wog. Kostbare Edelsteine waren daran, und sie paßte auf Davids Haupt. Die Beute der Stadt führte er in großer Menge weg.',
        3: 'Das Volk aber, das darin war, führte er heraus. Dann legte er Feuerbrände an und hieb und stach mit Eisen darein. So tat David mit all den anderen Ammoniterstädten. Dann kehrte David mit dem ganzen Volk nach Jerusalem zurück.',
        4: 'Hernach kam es nochmals mit den Philistern in Gezer zum Kampf. Damals erlegte der Chusatite Sibkai den Sippai, eines der Riesenkinder. So wurden sie gedemütigt.',
        5: 'Nochmals war ein Kampf mit den Philistern. Da schlug Jairs Sohn Elchanan den Gatiter Lachmi, Goliats Bruder, dessen Speerschaft einem Weberbaume glich.',
        6: 'Nochmals war ein Kampf bei Gat. Da war ein riesenlanger Mensch, der je sechs Finger und Zehen hatte, also vierundzwanzig, und der gleichfalls von den Riesen stammte.',
        7: 'Als er Israel höhnte, schlug ihn Jonatan, der Sohn Simeas, des Bruders Davids.',
        8: 'Diese stammten von den Riesen zu Gat und fielen durch Davids und seiner Diener Hand.',
    },
    21: {
        1: 'Satan aber trat gegen Israel auf und reizte David zur Zählung Israels.',
        2: 'So gebot David Joab und den Volksobersten: "Auf! Zählt Israel von Beerseba bis Dan, und bringt mir Bescheid, daß ich weiß, wieviel ihrer sind!"',
        3: 'Da sprach Joab: "Mag der Herr sein Volk, wie es ist, noch hundertfach vermehren! Sind sie nicht alle dem König, meinem Herrn, untertan? Warum verlangt dies mein Herr? Warum soll es Israel zur Schuld werden?"',
        4: 'Aber des Königs Befehl zwang Joab. Da zog Joab aus, durchwanderte ganz Israel und kam wieder nach Jerusalem.',
        5: 'Und Joab gab David die Zahl aus der Volkszählung an: Ganz Israel zählte 1.100.000 und Juda 470.000 schwertgerüstete Männer.',
        6: 'Er hatte aber Levi und Benjamin nicht mitgemustert. Denn des Königs Befehl war Joab ein Greuel.',
        7: 'Gott aber mißfiel diese Sache, und so schlug er Israel.',
        8: 'Da sprach David zu Gott: "Ich habe schwer gesündigt durch das, was ich getan. Nun aber vergib Deinem Knechte die Schuld! Denn ich habe töricht gehandelt."',
        9: 'Da sprach der Herr zu Gad, dem Seher Davids, also:',
        10: '"Auf! Sprich zu David: \'So spricht der Herr: Ich lege dreierlei dir vor. Eins wähle dir davon, daß ich\'s dir antue!\'"',
        11: 'Da ging Gad zu David und sprach zu ihm: "So spricht der Herr: \'Wähledir!',
        12: 'Entweder Hungersnot drei Jahre lang oder drei Monate Flucht vor deinen Widersachern, wobei dich deiner Feinde Schwert ereilt, oder drei Tage lang das Schwert des Herrn und Pest im Lande, daß der Engel des Herrn das Gesamtgebiet von Israel wüst macht.\' Nun sieh zu, was ich dem bescheiden soll, der mich gesandt!"',
        13: 'Da sprach David zu Gad: "Mir ist sehr bange. Doch möchte ich lieber in die Hand des Herrn fallen. Denn sein Erbarmen ist sehr groß. Aber in Menschenhand möchte ich nicht fallen."',
        14: 'So schickte der Herr eine Pest über Israel, und aus Israel fielen 70.000 Mann.',
        15: 'Gott sandte auch einen Engel nach Jerusalem, es zu verheeren. Als er es verheerte, sah der Herr darein und ließ sich das Unheil gereuen. Er sprach zum Engel, der die große Verheerung anrichtete: "Zieh deine Hand jetzt ab!" Eben stand des Herrn Engel bei der Tenne des Jebusiters Ornan.',
        16: 'Als nun David seine Augen erhob, sah er den Engel des Herrn zwischen Erde und Himmel stehen, in der Hand ein gezücktes Schwert, gegen Jerusalem ausgestreckt. Da fielen David und die Ältesten, mit härenen Gewändern bedeckt, auf ihr Antlitz.',
        17: 'Und David sprach zu Gott: "Habe nicht ich befohlen, das Volk zu zählen? Ich bin es also, der gesündigt und übel gehandelt hat. Was aber haben diese Schafe getan? Herr, mein Gott! Deine Hand sei gegen mich und mein Haus, nicht aber gegen Dein Volk zum Schlagen bereit!"',
        18: 'Der Engel des Herrn aber hatte Gad angewiesen, David zu melden, David möge hinaufgehen und einen Altar für den Herrn auf der Tenne des Jebusiters Ornan errichten.',
        19: 'Da ging David hinauf nach Gads Wort, das er im Namen des Herrn ausgesprochen.',
        20: 'Ornan sah wiederholt den Engel. Seine vier Söhne bei ihm aber versteckten sich. Ornan drosch gerade Weizen.',
        21: 'So kam David zu Ornan. Ornan aber blickte auf und sah David. Da ging er aus der Tenne und verneigte sich vor David bis zum Boden.',
        22: 'Da sprach David zu Ornan: "Gib mir den Tennenplatz, daß ich darauf für den Herrn einen Altar baue! Gib ihn mir für den vollen Betrag! Damit werde die Seuche vom Volk abgewehrt!"',
        23: 'Da sprach Ornan zu David: "Nimm ihn dir! Mein Herr, der König, tue, was ihm gefällt! Ich gebe dir die Rinder zu den Brandopfern, die Dreschschlitten zum Holz und den Weizen zum Speiseopfer. All dies gebe ich dir."',
        24: 'Da sprach der König David zu Ornan: "Nein! Ich will ihn um den vollen Betrag käuflich erwerben. Denn ich nehme für den Herrn nicht das weg, was dir gehört, um ein Brandopfer umsonst darzubringen.",',
        25: 'So gab David dem Ornan für den Platz die Summe von 600 Goldringen.',
        26: 'Dann baute David dort einen Altar für den Herrn und brachte Brand- und Dankopfer dar. Und als er den Herrn anrief, antwortete ihm dieser auf dem Brandopferaltar mit Feuer vom Himmel.',
        27: 'Und der Herr befahl dem Engel, sein Schwert wieder in die Scheide zu stecken.',
        28: 'Damals, als David wahrnahm, daß ihm der Herr auf der Tenne des Jebusiters Ornan Antwort gab, opferte er dort.',
        29: 'Des Herrn Wohnung aber, die Moses in der Wüste gefertigt hatte, und der Brandopferaltar waren damals auf der Höhe von Gibeon.',
        30: 'David aber konnte nicht vor ihm erscheinen, Gott zu befragen. Denn er war vor dem Schwerte des Engels des Herrn erschrocken.',
    },
    22: {
        1: 'Und David sprach: "Dies hier sei das Haus Gottes, des Herrn, und dies der Altar für die Brandopfer Israels."',
        2: 'Dann befahl David, die Fremdlinge im Lande Israel zu sammeln. Hierauf bestellte er Steinmetzen, um Quadersteine zum Bau des Gotteshauses zu behauen.',
        3: 'Ferner beschaffte David eine Menge Eisen für die Nägel zu den Torflügeln und für die Klammern und eine solche Menge Erz, daß man es nicht wägen konnte,',
        4: 'auch unzählige Zedernbalken. Denn die Sidonier und Tyrier brachten David Zedernbalken in Menge.',
        5: 'David sagte nämlich: "Mein Sohn Salomo ist noch jung und zart. Das Haus aber, das für den Herrn zu bauen ist, muß überaus groß werden, daß es als Ruhm und Zier für alle Länder dastehe. So will ich es denn vorbereiten." Und so beschaffte David vor seinem Tode Vorrat in Menge.',
        6: 'Dann rief er seinen Sohn Salomo und gebot ihm, ein Haus dem Herrn, dem Gott Israels, zu bauen.',
        7: 'David sprach zu seinem Sohne Salomo: "Ich habe im Sinne gehabt, ein Haus für den Namen des Herrn, meines Gottes, zu bauen.',
        8: "Da erging aber das Wort des Herrn an mich: 'Du hast in Menge Blut vergossen und große Kriege unternommen. So darfst du meinem Namen kein Haus erbauen, weil du viel Blut auf Erden vergossen hast.",
        9: 'Doch siehe! Ein Sohn wird dir geboren. Er wird ein Mann der Ruhe sein. Und ich verschaffe ihm Ruhe vor all seinen Feinden ringsumher. Er heißt ja Salomo. Und Ruhe und Frieden gebe ich in seinen Tagen Israel.',
        10: "Er baut ein Haus für meinen Namen. Er ist mir Sohn und ich ihm Vater. Ich gründe seinen königlichen Thron für alle Zeiten über Israel.'",
        11: 'Nun, mein Sohn! Der Herr sei mit dir, daß es dir gelinge und du das Haus des Herrn, deines Gottes, bauest, wie er dir verheißen hat!',
        12: 'Nur gebe dir der Herr Verstand und Klugheit und bestelle dich über Israel, daß du des Herrn, deines Gottes, Lehre beachtest!',
        13: 'Dann hast du Glück, wenn du die Satzungen und Rechte einhältst, die der Herr dem Moses für Israel geboten. Sei stark und mutig! Sei nicht furchtsam und nicht ängstlich!',
        14: 'Bei meiner Armut habe ich für das Haus des Herrn 100.000 Talente Gold beschafft und eine Million Silber, dazu so viel Erz und Eisen, daß es nicht zu wägen ist; in solcher Masse ist es da. Auch Balken und Steine habe ich beschafft, und du wirst noch mehr dazutun.',
        15: 'Auch Werkleute, Steinhauer, Maurer und Zimmerleute sind bei dir in Menge und allerlei Kunstverständige für jegliche Arbeit',
        16: 'in Gold, Silber, Erz und Eisen ohne Zahl. Auf! Geh ans Werk! Der Herr sei mit dir!"',
        17: 'Dann befahl David allen Fürsten Israels, seinem Sohne Salomo beizustehen:',
        18: '"Ist denn nicht der Herr, euer Gott, mit euch gewesen und hat euch ringsum Ruhe verschafft? Er hat ja in meine Hand des Landes Bewohner gegeben, und das Land hat sich dem Herrn und seinem Volke unterwerfen müssen.',
        19: 'So richtet euer Herz und euren Sinn darauf, den Herrn, euren Gott, zu suchen! Auf! Baut Gottes, des Herrn, Heiligtum,',
    },
    23: {
        1: 'Als David alt und lebenssatt geworden war, bestellte er seinen Sohn Salomo zum König über Israel.',
        2: 'Er versammelte alle Fürsten Israels, ebenso die Priester und die Leviten.',
        3: 'Und die Leviten wurden von dreißig Jahren an und darüber gezählt. Ihre Kopfzahl war 38.000 Mann.',
        4: '"Von diesen sollen 24.000 der Arbeit am Hause des Herrn vorstehen und 6.000 Amtleute und Richter sein!',
        5: '4.000 seien Torhüter, und 4.000 sollen den Herrn mit den Spielgeräten preisen, die ich zum Lobpreis mache!"',
        6: 'David teilte sie in Abteilungen nach den Levisöhnen Gerson, Kehat und Merari.',
        7: 'Zu den Gersoniten gehörten Ladan und Simei.',
        8: 'Ladans Söhne sind das Oberhaupt Jechiel, Zetam und Joel, drei.',
        9: 'Simeis Söhne sind Selomit, Chaziel und Haran, drei. Diese sind die Familienhäupter Ladans.',
        10: 'Simeis Söhne waren auch Jachat, Zina, Jëus und Beria. Dies sind die Söhne Simeis, vier.',
        11: 'Jachat war das Oberhaupt und Zina der zweite. Jëus aber und Beria hatten nur wenig Kinder, so daß sie bloß eine Familie, eine Amtsklasse bildeten.',
        12: 'Kehats Söhne sind Amram, Ishar, Chebron und Uzziel, vier.',
        13: 'Amrams Söhne sind Aaron und Moses. Aaron aber wurde ausgesondert, um für immer hochheilig geweiht zu sein, er und seine Söhne, damit sie beständig vor dem Herrn räucherten, ihm dienten und mit seinem Namen segneten.',
        14: 'Moses aber war der Mann Gottes. Seine Söhne wurden zum Levitenstamm gerechnet.',
        15: 'Mosis Söhne sind Gersom und Eliezer.',
        16: 'Gersoms Söhne sind: das Oberhaupt Sebuel.',
        17: 'Eliezers Söhne sind: das Oberhaupt Rechabja; andere Söhne hatte Eliezer nicht. Dagegen waren Rechabjas Söhne überaus zahlreich.',
        18: 'Ishars Söhne sind: das Oberhaupt Selomit.',
        19: 'Chebrons Söhne sind: das Oberhaupt Jeriahu, Amarja, der zweite, Jachaziel, der dritte, und Jekamam, der vierte.',
        20: 'Uzziels Söhne sind das Oberhaupt Mika und Isia, der zweite,',
        21: 'Meraris Söhne sind Machli und Musi. Machlis Söhne sind Eleazar und Kis.',
        22: 'Eleazar starb, ohne Söhne zu hinterlassen. Er hatte nur Töchter. Diese heirateten die Söhne des Kis.',
        23: 'Musis Söhne sind Machli, Eder und Jeremot, drei.',
        24: 'Dies sind Levis Söhne nach ihren Familien, die Familienhäupter nach ihrer Musterung, nach der Zahl der Namen, Kopf für Kopf, die beim Dienste am Hause des Herrn beschäftigt waren, von zwanzig Jahren und darüber.',
        25: 'Denn David sprach: "Der Herr, Israels Gott, hat seinem Volke Ruhe verliehen und wohnt in Jerusalem für alle Zeiten."',
        26: 'So brauchten auch die Leviten die Wohnung nicht mehr zu tragen und keines der zu ihrem Dienst erforderlichen Geräte.',
        27: 'Denn nach Davids letzten Befehlen wurde die Zahl der Levisöhne von den Zwanzigjährigen an berechnet.',
        28: 'Ihre Amtspflicht bestand in der Unterstützung der Aaronssöhne beim Dienst im Hause des Herrn, als Aufseher über die Vorhöfe und Zellen und über die Reinigung alles Heiligen sowie in den Dienstverrichtungen am Gotteshause,',
        29: 'ferner in der Besorgung der reihenweise aufgelegten Brote, des Feinmehls zum Speiseopfer und der ungesäuerten Fladen, der Pfanne und des Eingerührten, eines jeden Hohl- und Längenmaßes,',
        30: 'ferner darin, daß sie jeden Morgen hintraten, dem Herrn zu danken und ihn zu preisen, ebenso am Abend,',
        31: 'und bei jeder Darbringung von Brandopfern für den Herrn an den Sabbaten, Neumonden und Festen, soviel ihrer nach Vorschrift beständig vor dem Herrn darzubringen waren.',
        32: 'So sollten sie die Geschäfte am Bundeszelt tun und die Geschäfte am Heiligtum, ferner die Geschäfte bei ihren Brüdern, den Aaronssöhnen, während des Dienstes am Hause des Herrn.',
    },
    24: {
        1: 'Auch die Aaronssöhne hatten ihre Abteilungen. Die Aaronssöhne waren Nadab, Abihu, Eleazar und Itamar.',
        2: 'Nadab und Abihu aber starben vor ihrem Vater, ohne Söhne zu hinterlassen. So wurden Eleazar und Itamar Priester.',
        3: 'David teilte sie mit Sadok von Eleazars Söhnen und mit Achimelek von den Söhnen Itamars je nach ihrem Amt in ihren Dienst ein.',
        4: 'Nun waren Eleazars Söhne in den Sippenhäuptern zahlreicher als Itamars Söhne. Sie teilten sich so, daß auf Eleazars Söhne sechzehn und auf die Itamars acht Familienhäupter kamen.',
        5: 'Sie teilten sie durch das Los, die einen wie die anderen. Denn es gab Fürsten des Heiligtums und Fürsten Gottes sowohl bei Eleazars als bei Itamars Söhnen.',
        6: 'Und Netanels Sohn, Semaja, der Schreiber aus der Levitenzahl, schrieb sie vor dem König, den Fürsten und dem Priester Sadok auf. Je eine Familie wurde dabei von Itamar und je zwei von Eleazar ausgelost.',
        7: 'Das erste Los fiel auf Jojarib, das zweite auf Jedaja,',
        8: 'das dritte auf Charim, das vierte auf Seorim,',
        9: 'das fünfte auf Malkia, das sechste auf Mijjamin,',
        10: 'das siebte auf Hakkos, das achte auf Abia,',
        11: 'das neunte auf Jesua, das zehnte auf Sekanjahu,',
        12: 'das elfte auf Eljasib, das zwölfte auf Jakin,',
        13: 'das dreizehnte auf Chuppa, das vierzehnte auf Jeseb,',
        14: 'das fünfzehnte auf Bilga, das sechzehnte auf Immer,',
        15: 'das siebzehnte auf Chezir, das achtzehnte auf Happisses,',
        16: 'das neunzehnte auf Petachja, das zwanzigste auf Jechezkel,',
        17: 'das einundzwanzigste auf Jakin, das zweiundzwanzigste auf Gamul,',
        18: 'das dreiundzwanzigste auf Delaja und das vierundzwanzigste auf Maazja.',
        19: 'Das war ihre Amtsordnung für ihren Dienst, der darin bestand, daß sie des Herrn Haus nach der ihnen von ihrem Vater Aaron gegebenen Vorschrift betraten, wie es ihm der Herr, Israels Gott, geboten hatte.',
        20: 'Was die übrigen Levisöhne betrifft, so stammte von Amrams Söhnen Subael her, von Subaels Söhnen Iechdejahu,',
        21: 'von Rechabjahu, und zwar den Rechabjahusöhnen, das Oberhaupt Issia,',
        22: 'von den Ishariten Selomot, von Selomots Söhnen Jachat.',
        23: 'Jerias Söhne sind Amarja, der zweite, Jachaziel, der dritte, und Jekaman, der vierte.',
        24: 'Uzziels Söhne sind: Mika, von Mikas Söhnen Samir.',
        25: 'Mikas Bruder ist Issia; von den Söhnen Issias Zakarja.',
        26: 'Meraris Söhne sind Machli und Musi, die Söhne seines Sohnes Jaazia.',
        27: 'Meraris Söhne von seinem Sohn Jaaziahu sind Soham, Zakkur und Ibri.',
        28: 'Von Machli stammte Eleazar. Dieser hatte keine Söhne.',
        29: 'Von Kis: die Söhne des Kis: Jerachmeel.',
        30: 'Des Musi Söhne sind Machli, Eder und Jerimot. Dies sind die Levitensöhne nach ihren Familien.',
        31: 'Auch sie warfen Lose, wie ihre Brüder, die Söhne Aarons, vor König David, vor Sadok und Achimelek sowie vor den Familienhäuptern der Priester und Leviten, die Familienhäupter ebenso wie ihre jüngeren Brüder.',
    },
    25: {
        1: 'Ferner bestellte David Dienstobere für die Dienstleistung der Söhne Asaphs, Hemans und Jedutuns, die mit Zithern, Harfen und Zimbeln vorspielen sollten. Es erfolgte aber eine Zählung der mit diesem Dienste Beschäftigten.',
        2: 'Von Asaphs Söhnen standen Zakkur, Joseph, Netanja und Asarela, Asaphs Söhne, unter Asaph, der nach des Königs Geheiß vorspielte.',
        3: 'Von Jedutun standen Jedutuns Söhne Gedalja, Suri, Jesaja, Chasabja und Mattitja, sechs, mit Zithern unter ihrem Vater Jedutun, der beim Danksagen und beim Lobpreise des Herrn vorspielte.',
        4: 'Von Heman waren es Hemans Söhne Bukkiahu, Mattanjahu, Uzziel, Sebuel, Jerimot, Chananja, Chanani, Eliata, Giddalti, Romamtiezer, Josbekasa, Malloti, Hotir und Machaziot.',
        5: 'Dies alles sind Söhne Hemans, des königlichen Sehers in göttlichen Dingen und Zeichendeuters. Gott schenkte Heman vierzehn Söhne und drei Töchter.',
        6: 'Diese alle standen unter ihrem Vater beim Gesang im Hause des Herrn, mit Zimbeln, Harfen und Zithern beim Dienst im Gotteshause unter dem König, Asaph, Jedutun und Heman.',
        7: 'Ihre Zahl nebst der ihrer Brüder, die in den Liedern des Herrn wohlerfahren waren, insgesamt Meister, betrug 288.',
        8: 'Sie warfen Lose für den Dienst, für den der jüngeren und für den der Älteren, für Meister und Schüler.',
        9: 'Das erste Los Asaphs fiel auf Joseph, das zweite auf Gedalja; er, seine Brüder und Söhne waren zusammen zwölf,',
        10: 'das dritte auf Zakkur; seine Söhne und Brüder: zwölf,',
        11: 'das vierte auf Isri; seine Söhne und Brüder: zwölf,',
        12: 'das fünfte auf Netanjahu; seine Söhne und Brüder: zwölf,',
        13: 'das sechste auf Bukkiahu; seine Söhne und Brüder: zwölf,',
        14: 'das siebte auf Jesarela; seine Söhne und Brüder: zwölf,',
        15: 'das achte auf Jesajahu; seine Söhne und Brüder: zwölf,',
        16: 'das neunte auf Mattanjahu; seine Söhne und Brüder: zwölf,',
        17: 'das zehnte auf Simei; seine Söhne und Brüder: zwölf,',
        18: 'das elfte auf Azarel; seine Söhne und Brüder: zwölf,',
        19: 'das zwölfte auf Chasabja; seine Söhne und Brüder: zwölf,',
        20: 'das dreizehnte auf Subael; seine Söhne und Brüder: zwölf,',
        21: 'das vierzehnte auf Mattijahu; seine Söhne und Brüder: zwölf,',
        22: 'das fünfzehnte auf Jeremot; seine Söhne und Brüder: zwölf,',
        23: 'das sechzehnte auf Chananjabu; seine Söhne und Bruder: Zwölf,',
        24: 'das siebzehnte auf Josbekasa; seine Söhne und Brüder: zwölf,',
        25: 'das achtzehnte auf Chanani; seine Söhne und Brüder: zwölf,',
        26: 'das neunzehnte auf Malloti; seine Söhne und Brüder: zwölf,',
        27: 'das zwanzigste auf Eliata; seine Söhne und Brüder: zwölf,',
        28: 'das einundzwanzigste auf Hotir; seine Söhne und Brüder: zwölf,',
        29: 'das zweiundzwanzigste auf Giddalti; seine Söhne und Brüder: zwölf,',
        30: 'das dreiundzwanzigste auf Machaziot; seine Söhne und Brüder: zwölf,',
        31: 'das vierundzwanzigste auf Romamtiezer; seine Söhne und Brüder: zwölf.',
    },
    26: {
        1: 'Bei den Torhüterabteilungen war von den Korachiten Meselemjahu, Kores Sohn von den Asaphsöhnen.',
        2: 'Und Meselemjahus Söhne sind Zakarja, der Erstgeborene, Iediael, der zweite, Zabadjahu, der dritte, Jatmiel, der vierte,',
        3: 'Elam, der fünfte, Jochanan, der sechste, Eljoënai, der siebte.',
        4: 'Auch Obededom hatte Söhne: Semaja, den Erstgeborenen, Jozabad, den zweiten, Joach, den dritten, Sakar, den vierten, Netanel, den fünften,',
        5: 'Ammiel, den sechsten, Issakar, den siebten, und Pëulletai, den achten. Denn ihn hatte Gott gesegnet.',
        6: 'Auch seinem Sohne Semaja waren Söhne geboren worden, die in ihrer Familie Führer waren. Denn sie waren tapfere Männer.',
        7: 'Semajas Söhne waren Otnai und Rephael, Obed, Elzabad, Elihu und Semakjahu, seine Brüder, tüchtige Leute.',
        8: 'Diese alle stammen von Obededoms Söhnen ab, sie, ihre Söhne und Brüder, tüchtige Leute, zum Dienste wohlbefähigt, zweiundsechzig von Obededom.',
        9: 'Auch Meselemja hatte achtzehn Söhne und Brüder, tüchtige Leute.',
        10: 'Chosas Söhne, die zu Meraris Söhnen gehörten, waren: das Oberhaupt Simri. Denn kein Erstgeborener war mehr dagewesen, und so machte ihn sein Vater zum Oberhaupt.',
        11: 'Chilkiahu war der zweite, Tebaljahu der dritte und Zakarjahu der vierte. Chosas Söhne und Brüder waren insgesamt dreizehn.',
        12: 'Diesen Abteilungen der Torhüter, und zwar den Sippenhäuptern, fielen ebenso wie ihren Brüdern die amtlichen Dienstleistungen am Hause des Herrn zu.',
        13: 'Man warf das Los für die einzelnen Tore nach Familien, für die Jüngeren wie für die Älteren.',
        14: 'Da fiel das Los nach Osten auf Selemjahu. Auch für seinen Sohn Zakarjahu, einen klugen Ratgeber, warf man das Los, und das Los fiel für ihn nach Norden,',
        15: 'für Obededom nach Süden und für seine Söhne auf das Vorratshaus,',
        16: 'für Suppim und für Chosa nach Westen samt dem Ausgangstor an der aufsteigenden Straße, ein Wachtposten neben dem anderen.',
        17: 'Nach Osten zu waren es sechs Leviten, nach Norden zu täglich vier, nach Süden täglich vier, am Vorratshause je zwei,',
        18: 'am Festungsturme nach Westen vier für die Straße und zwei für den Festungsturm.',
        19: 'Dies sind die Abteilungen der Torhüter von den Söhnen des Korachiten und von den Merarisöhnen.',
        20: 'Ihre Brüder aber, die Leviten, beaufsichtigten die Vorräte des Gotteshauses und die heiligen Gaben.',
        21: 'Ladans Söhne, die Söhne des Gersoniten Ladan, die Familienhäupter Ladans, des Gersoniters, die Jechieliter,',
        22: 'die Söhne der Jechieliter, Zetam und sein Bruder Joel, beaufsichtigten die Vorräte im Hause des Herrn.',
        23: 'Bei den Amramiten, Ishariten, Chebroniten und Ozzieliten',
        24: 'war Sebuel, Gersoms Sohn und Mosis Enkel, Oberaufseher über die Vorräte.',
        25: 'Bei seinen Brüdern von Eliezer her war sein Sohn Rechabjahu, dessen Sohn Jesajahu, dessen Sohn Joram, dessen Sohn Zikri und dessen Sohn Selomit.',
        26: 'Dieser Selomit und seine Brüder beaufsichtigten alle Vorräte an heiligen Gaben, die König David und die Familienhäupter der Anführer von Tausend- und Hundertschaften sowie die Heerführer geweiht hatten.',
        27: 'Sie hatten sie aus den Kriegen und aus der Beute geweiht, um des Herrn Haus sicherzustellen.',
        28: 'Auch alles, was der Seher Samuel, Saul, des Kis Sohn, Abner, Ners Sohn, und Serujas Sohn Joab geweiht hatten, alles Geweihte stand unter Selomits und seiner Brüder Aufsicht.',
        29: 'Von den Ishariten waren Kenanjahu und seine Söhne für die Geschäfte draußen in Israel als Amtsleute und Richter bestimmt.',
        30: 'Von den Chebroniten standen Chasabjahu und seine Brüder, 1.700 tüchtige Leute, der Verwaltung Israels westlich vom Jordan vor in allen Sachen des Herrn und im Dienste des Königs.',
        31: 'Zu den Chebroniten gehörte Jeria, das Oberhaupt der Chebroniter nach ihren Sippen und Familien. Im vierzigsten Regierungsjahre Davids waren sie aufgesucht worden, und unter ihnen waren zu Jazer in Gilead tüchtige Leute.',
        32: 'Seine Brüder, tüchtige Leute, 2.700 Familienhäupter, setzte König David über die Rubeniten, Gaditen und den Halbstamm Manasse in allen Sachen Gottes und des Königs.',
    },
    27: {
        1: 'Israels Söhne nach ihrer Zahl, die Familienhäupter und die Anführer der Tausend- und Hundertschaften, ebenso ihre Amtleute dienten dem König in allen Sachen der Abteilungen, die Monat für Monat, alle Monate des Jahres, antraten und abzogen, jede Abteilung 24.000 Mann stark.',
        2: 'Über der ersten Abteilung im ersten Monat stand Zabdiels Sohn Josobeam. Bei seiner Abteilung waren 24.000 Mann.',
        3: 'Er stammte von des Peres Söhnen und war das Oberhaupt aller Heerführer im ersten Monat.',
        4: 'Über der Abteilung des zweiten Monats stand der Achochiter Dodai, über seiner Abteilung und über der des Fürsten. Bei seiner Abteilung waren 24.000 Mann.',
        5: 'Der Obere des dritten Heeres für den dritten Monat war Benajahu, des Priesters Jojada Sohn als Oberhaupt. Bei seiner Abteilung waren 24.000 Mann.',
        6: 'Dieser Benajahu war der Held unter den Dreißig und stand den Dreißig vor. Seine Abteilung war die seines Sohnes Ammizadab.',
        7: 'Der vierte für den vierten Monat war Joabs Bruder Asahel. Sein Sohn Zabadja war sein Nachfolger. Bei seiner Abteilung waren 24.000 Mann.',
        8: 'Der fünfte für den fünften Monat war der Oberste Samhut, der Izrachiter. Bei seiner Abteilung waren 24.000 Mann.',
        9: 'Der sechste für den sechsten Monat war der Tekoiter Ira, des Ikkes Sohn. Bei seiner Abteilung waren 24.000 Mann.',
        10: 'Der siebte für den siebenten Monat war der Peloniter Cheles von den Söhnen Ephraims. Bei seiner Abteilung waren 24.000 Mann.',
        11: 'Der achte für den achten Monat war der Chusatiter Sibbeka aus den Zarechitern. Bei seiner Abteilung waren 24.000 Mann.',
        12: 'Der neunte für den neunten Monat war der Anatotiter Eliezer aus den Benjaminiten. Bei seiner Abteilung waren 24.000 Mann.',
        13: 'Der zehnte für den zehnten Monat war der Netophatiter Maharai aus den Zarechitern. Bei seiner Abteilung waren 24.000 Mann.',
        14: 'Der elfte für den elften Monat war der Piratoniter Benaja von den Söhnen Ephraims. Bei seiner Abteilung waren 24.000 Mann.',
        15: 'Der zwölfte für den zwölften Monat war der Netophatiter Cheldai aus Otniel. Bei seiner Abteilung waren 24.000 Mann.',
        16: 'Über den Stämmen Israels standen Fürsten: von den Rubeniten Zikris Sohn Eliezer, von den Simeoniten Maakas Sohn Sephatjahu,',
        17: 'von Levi Kemels Sohn Chasabja, von Aaron Sadok,',
        18: 'von Juda Elihu, einer der Brüder Davids, von Issakar Mikaels Sohn Omri,',
        19: 'von Zabulon Obadjahus Sohn Ismajahu, von Naphtali Azriels Sohn Jerimot,',
        20: 'von den Ephraimiten Azazjahus Sohn Hosea, vom Halbstamme Manasse Joel, Pedajahus Sohn,',
        21: 'vom Halbstamme Manasse in Gilead Zakarjahus Sohn Iddo, von Benjamin Abners Sohn Jaasiel,',
        22: 'von Dan Jerochams Sohn Azarel. - Dies sind die Fürsten der Stämme Israels.',
        23: 'Die Zahl derer von zwanzig Jahren und darunter hatte David nicht aufgenommen. Denn der Herr hatte gesagt, er mache Israel so zahlreich wie des Himmels Sterne.',
        24: 'Serujas Sohn Joab hatte mit der Zählung begonnen; aber er hatte sie nicht zu Ende gebracht. Denn deshalb entstand ein Zorn wider Israel. Die Zählung aber war nicht vollständig in das Buch der Chronik des Königs David aufgenonunen worden.',
        25: 'Über den Vorräten des Königs stand Azmavet, Adiels Sohn, und über den Vorräten auf dem Feld, in den Städten, Dörfern und Türmen stand Jonatan, Uzziahus Sohn.',
        26: 'Über den Feldarbeitern beim Ackerbau stand Ezri, Kelubs Sohn.',
        27: 'Über den Weinbergen stand Simei von Nama. Und über dem, was in den Weinbergen an Weinvorräten war, stand Zabdi von Siphmi.',
        28: 'Über den Ölbäumen und Maulbeerfeigen in der Niederung stand Baal Chanan von Gader. Über den Ölvorräten Joas.',
        29: 'Über den Rindern, die in Saron weideten, stand Sitri von Saron. Über den Rindern in den Tälern stand Saphat, Adlais Sohn.',
        30: 'Über den Kamelen Obil, der Ismaelite, über den Eselinnen Jechdejahu Meronot.',
        31: 'Über den Schafen Jaziz, der Hagriter. Diese alle waren Oberbeamte über des Königs David Habe.',
        32: 'Jonatan, Davids Oheim, ein kluger und schriftkundiger Mann, war Rat. Jechiel, Hakmonis Sohn, war bei den Söhnen des Königs.',
        33: 'Achitophel war Rat beim König, und Chusai, der Arkiter, war der Freund des Königs.',
        34: 'Nach Achitophel aber waren es Jojada, Benajahus Sohn, und Ebjatar. Und Feldhauptmann des Königs war Joab.',
    },
    28: {
        1: 'Es versammelte David alle Oberen Israels, die Oberen der Stämme und die der Abteilungen, die dem König dienten, die Oberen der Tausend- und Hundertschaften, die Oberaufseher über das gesamte Eigentum und die Herden des Königs und seiner Söhne samt den Kämmerlingen, den Helden und allen kriegstüchtigen Männern nach Jerusalem.',
        2: 'Und König David stand da und sprach: "Auf mich hört, meine Brüder und mein Volk, hört mich! Im Sinne habe ich gehabt, ein Haus der Ruhe zu erbauen für des Herrn Bundeslade und für den Schemel der Füße unseres Gottes. Ich hatte schon das Bauen vorbereitet.',
        3: "Gott aber hat zu mir gesprochen: 'Du sollst kein Haus für meinen Namen bauen. Du bist ein Kriegsmann und hast Blut vergossen.'",
        4: 'Und dennoch wählte mich der Herr, Gott Israels, aus meinem ganzen Vaterhause, auf daß ich König über Israel für immer sei. Denn Juda hatte er zum Fürsten auserwählt und in dem Judahause meine Sippe, und unter meines Vaters Söhnen hat es ihm beliebt, mich über das gesamte Israel zum Könige zu machen.',
        5: 'Von allen meinen Söhnen - der Herr hat mir viele Söhne geschenkt - erwählte er meinen Sohn Salomo, auf daß er sitze auf des Herrn königlichem Throne über Israel.',
        6: "Er sprach zu mir: 'Mein Haus und meine Vorhöfe erbaue mir dein Sohn Salomo! Denn ihn erwählte ich mir zum Sohne, und ihm bin ich Vater.",
        7: "Und ich bestätige sein Königtum für alle Zeit, wenn er nur standhaft ist, um meine Satzungen und Rechte zu erfüllen, so wie es heute ist.'",
        8: 'Nun denn! Vor den Augen des gesamten Israel, vor des Herrn Gemeinde und auch vor unseres Gottes Ohren sei gesagt: Beachtet doch und suchet alle Satzungen des Herrn, eures Gottes, daß ihr dies treffliche Land behaltet und es auf eure Söhne nach euch ewiglich vererbet!',
        9: 'Du, Salomo, mein Sohn, hochschätze deines Vaters Gott und diene ihm mit ungeteiltem Herzen und mit williger Seele! Der Herr erforscht ja alle Herzen und kennt alles Dichten und Trachten. Suchst du ihn auf, dann läßt er sich von dir auch finden. Verläßt du ihn, verwirft er dich für immer.',
        10: 'Sieh zu! Dich hat der Herr erwählt, ein Haus zum Heiligtum zu bauen. Geh frisch ans Werk!"',
        11: 'Hierauf übergab David seinem Sohn Salomo den Plan der Vorhalle und den seiner Räume, seiner Schatzkammern, Obergemächer, inneren Kammern und des Raumes für die Deckplatte,',
        12: 'sowie den Plan für alles andere, was er noch im Sinne gehabt, für die Vorhöfe im Hause des Herrn und alle Zellen ringsum, für die Vorratskammern des Gotteshauses und die Schatzkammern für die Weihegaben,',
        13: 'für die Abteilungen der Priester und Leviten, für alle dienstlichen Verrichtungen im Hause des Herrn und für alle Geräte für den Dienst im Hause des Herrn.',
        14: 'An Gold soviel, wie für die Geräte zu den einzelnen Dienstleistungen nötig war, ebensoviel zu allen silbernen Geräten,',
        15: 'ferner den Bedarf für die goldenen Leuchter und ihre goldenen Lampen, nach dem Gewichte eines jeden Leuchters mit seiner Lampe, ferner den für die silbernen Leuchter, nach dem Gewichte eines jeden Leuchters mit seiner Lampe, gemäß der Verwendung der verschiedenen Leuchter,',
        16: 'ferner den Goldbedarf für die Schaubrottische, für jeden einzelnen Tisch, sodann das Silber für die einzelnen Tische,',
        17: 'ferner für die Gabeln, Becken und Kannen von gediegenem Golde und für die goldenen Becher, soviel jeder Becher wiegen sollte, ebenso für die silbernen Becher,',
        18: 'für den Räucheraltar geläutertes Gold nach Bedarf, ebenso für das Muster des Wagens, für die goldenen Cherube, die sich ausbreiten und die Bundeslade des Herrn überdecken.',
        19: 'Über all das hatte er ihn durch eine vom Herrn veranlaßte Schrift belehrt, über alle Arbeiten nach dem Plane.',
        20: 'Dann sprach David zu seinem Sohne Salomo: "Geh mutig und tapfer ans Werk! Sei nicht furchtsam und nicht bang! Denn der Herr, mein Gott, ist mit dir. Er läßt nicht von dir und verläßt dich nicht, bis alle Arbeiten für den Dienst am Hause des Herrn fertig sind.',
        21: 'Schon sind die Abteilungen der Priester und der Leviten für den ganzen Dienst am Gotteshause bereit, und für jedes Geschäft hast du allerlei kunstfertige, zu jedem Dienst bereite Leute. Ebenso stehen dir die Obersten und das ganze Volk stets zu Diensten."',
    },
    29: {
        1: 'Und König David sprach zu der ganzen Gemeinde: "Meinen Sohn Salomo allein hat Gott erwählt. Er ist aber noch jung und zart, und das Werk ist gewaltig. Denn nicht für einen Menschen ist die Burg bestimmt, sondern für Gott den Herrn.',
        2: 'Und so habe ich mit all meiner Kraft für meines Gottes Haus Gold zu dem goldenen Gerät beschafft, Silber zum silbernen, Erz zum ehernen, Eisen zum eisernen und Holz zum hölzernen, ferner Onyxsteine und glänzende und bunte Steine zu Füllungen, sowie sonstige kostbare Steine und in Menge Alabasterstein.',
        3: 'Weiter gebe ich in meinem Eifer für meines Gottes Haus das, was ich an erspartem Gold und Silber besitze, zum Hause meines Gottes, mehr als ich bereits für das heilige Haus beschafft habe,',
        4: '3.000 Goldtalente Ophirgold und 7.000 Talente geläutertes Silber, um die Wände des Hauses zu überziehen,',
        5: 'alles Nötige an Gold und Silber und für jede Arbeit durch Künstlerhand. Wer ist nun bereit, heute für den Herrn mit vollen Händen zu geben?"',
        6: 'Da spendeten die Obersten der Familien, die Obersten der Stämme Israels, die Obersten der Tausend- und Hundertschaften und die Obersten im königlichen Dienste.',
        7: 'Sie gaben zum Bau des Gotteshauses 5.000 Goldtalente oder 10.000 Dariken, 10.000 Talente Silber, 18.000 Talente Erz und 100.000 Talente Eisen.',
        8: 'Wer Steine besaß, gab sie in den Schatz des Hauses des Herrn unter die Obhut des Gersoniters Jechiel.',
        9: 'Das Volk aber freute sich über ihre Freigebigkeit; denn mit ungeteiltem Herzen waren sie gegen den Herrn freigebig gewesen. Auch König David hatte sich recht darüber gefreut.',
        10: 'Da pries David den Herrn angesichts der ganzen Gemeinde. Und David sprach: "Gepriesen seist Du, Herr, Gott unseres Vaters Israel, von Ewigkeit zu Ewigkeit!',
        11: 'Dein ist die Größe, Macht und Herrlichkeit und Ruhm und Hoheit, Herr; denn Dein ist alles, so im Himmel wie auf Erden, Herr, die Herrschaft und der Vorrang über alle Hochgeborenen.',
        12: 'Der Reichtum und die Ehre kommen nur von Dir, und Du bist Herrscher über alles. In Deiner Hand steht Kraft und Macht. Bei Dir steht es, jemanden groß und stark zu machen.',
        13: 'Nun, unser Gott! Dir danken wir und preisen Deinen Namen voller Glanz.',
        14: 'Denn wer bin ich? Was ist mein Volk, daß wir soviel freiwillig spenden können? Von Dir stammt alles. Aus Deiner Hand bloß geben wir es Dir,',
        15: 'sind wir doch Fremdlinge vor Dir und Beisassen wie alle unsere Väter. Ein Schatten nur sind unsere Tage auf der Erde, hoffnungslos.',
        16: 'Herr, unser Gott! All diese Fülle, die wir jetzt beschafft, um Dir ein Haus für Deinen heiligen Namen zu erbauen, aus Deiner Hand stammt sie, und Dein ist alles.',
        17: 'Ich weiß, mein Gott, daß Du die Herzen prüfest, daß Du an Redlichkeit Gefallen hast; drum habe ich in Redlichkeit des Herzens alles dies gespendet. Und auch Dein Volk, das hier zugegen, ich sehe es mit Freuden Dir die Gaben bringen.',
        18: 'Herr! Unserer Väter Abraham, Isaak und Jakob Gott! Bewahre ewig diese guten Triebe im Herzen Deines Volkes und lenke hin sein Herz zu Dir!',
        19: 'Gib meinem Sohne Salomo ein ungeteiltes Herz, zu wahren Deine Vorschriften, Gebräuche und Verordnungen und alles dies zu tun und auch die Burg, die ich jetzt vorbereite, zu erbauen!"',
        20: 'Dann sprach David zu der ganzen Gemeinde: "Preist den Herrn, euren Gott!" Da pries die ganze Gemeinde den Herrn, ihrer Väter Gott. Sie neigten sich und warfen sich vor dem Herrn nieder und vor dem Könige.',
        21: 'Sie schlachteten für den Herrn Opfer und brachten dem Herrn Brandopfer am anderen Morgen dar: tausend Farren, tausend Widder, tausend Lämmer nebst ihren Trankopfern, dazu in Menge Schlachtopfer für ganz Israel.',
        22: 'Dann aßen sie und tranken vor dem Herrn an jenem Tage mit großer Freude. Dann machten sie Davids Sohn Salomo zum zweitenmal zum König und salbten ihn dem Herrn zum Fürsten und Sadok zum Priester.',
        23: 'So saß Salomo auf dem Throne des Herrn als König an seines Vaters David Statt, und er hatte Glück. Ganz Israel gehorchte ihm.',
        24: 'Auch alle Obersten und Helden sowie alle Söhne des Königs David unterwarfen sich dem König Salomo.',
        25: 'Und der Herr machte Salomo überaus groß in den Augen von ganz Israel und legte auf ihn königlichen Glanz, wie ihn vor ihm kein König von Israel besessen hatte.',
        26: 'David, Isais Sohn, hatte über ganz Israel geherrscht.',
        27: 'Die Zeit, die er über Israel herrschte, betrug vierzig Jahre. Zu Hebron regierte er sieben Jahre und zu Jerusalem dreiunddreißig Jahre.',
        28: 'Er starb in schönem Alter, satt an Lebenstagen, Reichtum und Ruhm. Und sein Sohn Salomo ward König an seiner Statt.',
        29: 'Des Königs David Geschichte aber, die frühere und die spätere, ist aufgezeichnet in der Geschichte des Sehers Samuel, in der Geschichte des Propheten Natan und in der Geschichte des Sehers Gad,',
        30: 'samt seiner ganzen Regierung, seinen Heldentaten und den Zeitläuften, die über ihn dahingegangen sind und über Israel und über all die anderen Reiche der Länder.',
    },
}
